    @staticmethod
    def _protected_resident_context_access_consumption_idempotency_scope(
        scope: WorkflowScope, subject_id: str, audience: str
    ) -> str:
        return canonical_digest(
            {
                "scope": scope.canonical_value(),
                "subject_id": subject_id,
                "audience": audience,
            }
        )

    @staticmethod
    def _protected_resident_context_access_consumption_authority_is_zero(
        authority: Any,
    ) -> bool:
        return all(value is False for value in authority.canonical_value().values())

    @staticmethod
    def _protected_resident_context_access_consumption_authority_columns(
        authority: Any,
    ) -> dict[str, bool]:
        return {
            (
                name
                if name.endswith("_authority_granted")
                else name.replace("_authorized", "_authority_granted")
            ): bool(value)
            for name, value in authority.canonical_value().items()
        }

    @classmethod
    def _protected_resident_context_access_consumption_claim_model(
        cls,
        request: WorkflowProtectedResidentContextAccessConsumptionClaimRequest,
        *,
        claim: WorkflowProtectedResidentContextAccessConsumptionClaim,
    ) -> WorkflowProtectedResidentContextAccessConsumptionClaimModel:
        values = cls._protected_resident_context_access_consumption_model_values(
            WorkflowProtectedResidentContextAccessConsumptionClaimModel, claim
        )
        values.update(
            idempotency_scope_id=cls._protected_resident_context_access_consumption_idempotency_scope(
                claim.scope, claim.consumer_subject_id, claim.consumer_audience
            ),
            idempotency_key=request.idempotency_key,
            consumption_authorization_audit_payload=(
                request.consumption_authorization_audit_payload
            ),
        )
        return WorkflowProtectedResidentContextAccessConsumptionClaimModel(**values)

    @classmethod
    def _protected_resident_context_access_attempt_model(
        cls,
        request: WorkflowProtectedResidentContextAccessConsumptionClaimRequest,
        *,
        attempt: WorkflowProtectedResidentContextAccessConsumptionAttempt,
    ) -> WorkflowProtectedResidentContextAccessAttemptModel:
        values = cls._protected_resident_context_access_consumption_model_values(
            WorkflowProtectedResidentContextAccessAttemptModel, attempt
        )
        values.update(
            lifecycle_attestation_payload={
                **request.lifecycle_attestation.digest_payload(),
                "canonical_digest": request.lifecycle_attestation.canonical_digest,
            },
            readiness_attestation_payload={
                **request.accessor_readiness_attestation.digest_payload(),
                "canonical_digest": request.accessor_readiness_attestation.canonical_digest,
            },
        )
        return WorkflowProtectedResidentContextAccessAttemptModel(**values)

    @classmethod
    def _protected_resident_context_access_result_model(
        cls, request: WorkflowProtectedResidentContextAccessConsumptionResultRequest
    ) -> WorkflowProtectedResidentContextAccessResultModel:
        result = request.result
        values = cls._protected_resident_context_access_consumption_model_values(
            WorkflowProtectedResidentContextAccessResultModel, result
        )
        values["accessor_receipt_payload"] = (
            None
            if request.receipt is None
            else {
                **request.receipt.digest_payload(),
                "canonical_digest": request.receipt.canonical_digest,
            }
        )
        return WorkflowProtectedResidentContextAccessResultModel(**values)

    @classmethod
    def _protected_resident_context_access_consumption_model_values(
        cls, model_type: Any, value: Any
    ) -> dict[str, object]:
        columns = {column.name for column in model_type.__table__.columns}
        values: dict[str, object] = {
            name: getattr(value, name)
            for name in columns
            if hasattr(value, name)
            and name
            not in {
                "state",
                "failure_class",
                "canonical_digest",
                "payload",
            }
            and not name.endswith("_authority_granted")
        }
        values.update(
            organization_id=value.scope.organization_id,
            environment_id=value.scope.environment_id,
            site_id=value.scope.site_id,
            **cls._protected_resident_context_access_consumption_authority_columns(value.authority),
            canonical_digest=value.canonical_digest,
            payload=value.digest_payload(),
        )
        if "state" in columns:
            values["state"] = getattr(value.state, "value", value.state)
        if "failure_class" in columns:
            failure_class = value.failure_class
            values["failure_class"] = (
                None if failure_class is None else getattr(failure_class, "value", failure_class)
            )
        return values

    @classmethod
    def _protected_resident_context_access_consumption_claim_from_row(
        cls, row: WorkflowProtectedResidentContextAccessConsumptionClaimModel
    ) -> WorkflowProtectedResidentContextAccessConsumptionClaim:
        claim = cast(
            WorkflowProtectedResidentContextAccessConsumptionClaim,
            cls._protected_resident_context_access_consumption_domain_from_payload(
                row.payload,
                row.canonical_digest,
                "WorkflowProtectedResidentContextAccessConsumptionClaim",
            ),
        )
        if (
            row.payload != claim.digest_payload()
            or row.consumption_authorization_audit_digest
            != canonical_digest(dict(row.consumption_authorization_audit_payload))
        ):
            cls._protected_resident_context_access_consumption_contract_violation()
        cls._protected_resident_context_access_consumption_assert_row_matches(row, claim)
        return claim

    @classmethod
    def _protected_resident_context_access_attempt_from_row(
        cls, row: WorkflowProtectedResidentContextAccessAttemptModel
    ) -> WorkflowProtectedResidentContextAccessConsumptionAttempt:
        attempt = cast(
            WorkflowProtectedResidentContextAccessConsumptionAttempt,
            cls._protected_resident_context_access_consumption_domain_from_payload(
                row.payload,
                row.canonical_digest,
                "WorkflowProtectedResidentContextAccessConsumptionAttempt",
            ),
        )
        cls._protected_resident_context_access_consumption_assert_row_matches(row, attempt)
        return attempt

    @classmethod
    def _protected_resident_context_access_result_from_row(
        cls, row: WorkflowProtectedResidentContextAccessResultModel
    ) -> WorkflowProtectedResidentContextAccessConsumptionResult:
        result = cast(
            WorkflowProtectedResidentContextAccessConsumptionResult,
            cls._protected_resident_context_access_consumption_domain_from_payload(
                row.payload,
                row.canonical_digest,
                "WorkflowProtectedResidentContextAccessConsumptionResult",
            ),
        )
        cls._protected_resident_context_access_consumption_assert_row_matches(row, result)
        return result

    @classmethod
    def _protected_resident_context_access_consumption_assert_row_matches(
        cls, row: Any, value: Any
    ) -> None:
        scalar_names = (
            name
            for name in value.__dataclass_fields__
            if name not in {"scope", "state", "failure_class", "authority", "canonical_digest"}
            and hasattr(row, name)
        )
        failure_class = getattr(value, "failure_class", None)
        if (
            any(getattr(row, name) != getattr(value, name) for name in scalar_names)
            or row.organization_id != value.scope.organization_id
            or row.environment_id != value.scope.environment_id
            or row.site_id != value.scope.site_id
            or (hasattr(row, "state") and row.state != value.state.value)
            or (
                hasattr(row, "failure_class")
                and row.failure_class != (None if failure_class is None else failure_class.value)
            )
            or row.canonical_digest != value.canonical_digest
            or row.payload != value.digest_payload()
            or {
                name: bool(getattr(row, name))
                for name in cls._protected_resident_context_access_consumption_authority_columns(
                    value.authority
                )
            }
            != cls._protected_resident_context_access_consumption_authority_columns(value.authority)
        ):
            cls._protected_resident_context_access_consumption_contract_violation()

    @classmethod
    def _protected_resident_context_access_consumption_domain_from_payload(
        cls,
        raw: dict[str, Any],
        stored_digest: str,
        class_name: str,
    ) -> Any:
        payload = dict(raw)
        payload["scope"] = WorkflowScope(**cast(dict[str, str], payload["scope"]))
        for name, value in tuple(payload.items()):
            if (
                value is not None
                and isinstance(value, str)
                and (name.endswith("_at") or name.endswith("_until") or name.endswith("_deadline"))
            ):
                payload[name] = datetime.fromisoformat(value)
        if "authority" in payload:
            payload["authority"] = WorkflowProtectedResidentContextAccessConsumptionAuthority(
                **cast(Any, payload["authority"])
            )
        if "state" in payload:
            payload["state"] = (
                WorkflowProtectedResidentContextAccessConsumptionAttemptState(str(payload["state"]))
                if class_name.endswith("Attempt")
                else WorkflowProtectedResidentContextAccessConsumptionResultState(
                    str(payload["state"])
                )
            )
        if payload.get("failure_class") is not None:
            payload["failure_class"] = (
                WorkflowProtectedResidentContextAccessConsumptionFailureClass(
                    str(payload["failure_class"])
                )
            )
        domain_types: dict[str, type[Any]] = {
            "WorkflowProtectedResidentContextAccessConsumptionClaim": (
                WorkflowProtectedResidentContextAccessConsumptionClaim
            ),
            "WorkflowProtectedResidentContextAccessConsumptionAttempt": (
                WorkflowProtectedResidentContextAccessConsumptionAttempt
            ),
            "WorkflowProtectedResidentContextAccessConsumptionResult": (
                WorkflowProtectedResidentContextAccessConsumptionResult
            ),
        }
        value = domain_types[class_name](**cast(Any, payload), canonical_digest=stored_digest)
        if canonical_digest(value.digest_payload()) != stored_digest:
            cls._protected_resident_context_access_consumption_contract_violation()
        return value

    def _protected_resident_context_access_result_matches(
        self,
        *,
        request: WorkflowProtectedResidentContextAccessConsumptionResultRequest,
        claim_row: WorkflowProtectedResidentContextAccessConsumptionClaimModel | None,
        attempt_row: WorkflowProtectedResidentContextAccessAttemptModel | None,
        observed_at: datetime,
    ) -> bool:
        if claim_row is None or attempt_row is None:
            return False
        try:
            claim = self._protected_resident_context_access_consumption_claim_from_row(claim_row)
            attempt = self._protected_resident_context_access_attempt_from_row(attempt_row)
            instruction = build_workflow_protected_resident_context_trusted_accessor_instruction(
                attempt
            )
            result = request.result
            receipt = request.receipt
            receipt_verifier = self._protected_resident_context_access_receipt_signature_verifier
            result_states = WorkflowProtectedResidentContextAccessConsumptionResultState
            uncertain_state = result_states.ACCESS_OUTCOME_UNCERTAIN
            receipt_valid = (
                receipt is None
                and result.state is uncertain_state
                and result.accessor_receipt_digest is None
                and result.completed_at is None
            ) or (
                receipt is not None
                and result.state is not uncertain_state
                and receipt.canonical_digest == canonical_digest(receipt.digest_payload())
                and receipt_verifier is not None
                and receipt_verifier.verify_receipt(receipt) is True
            )
        except Exception:
            return False
        return bool(
            receipt_valid
            and result.canonical_digest == canonical_digest(result.digest_payload())
            and result.access_id == attempt.access_id
            and result.consumption_claim_id == claim.claim_id
            and result.consumption_claim_digest == claim.canonical_digest
            and result.attempt_id == attempt.attempt_id
            and result.attempt_digest == attempt.canonical_digest
            and result.authorization_lease_id == claim.authorization_lease_id
            and result.authorization_lease_digest == claim.authorization_lease_digest
            and result.protected_resident_context_id == claim.protected_resident_context_id
            and result.protected_resident_context_digest
            == claim.protected_resident_context_digest
            == attempt.protected_resident_context_digest
            and result.scope == claim.scope == attempt.scope
            and result.consumer_subject_id == attempt.consumer_subject_id
            and result.consumer_audience == attempt.consumer_audience
            and result.consumer_contract_id == attempt.consumer_contract_id
            and result.consumer_contract_version == attempt.consumer_contract_version
            and result.purpose_id == attempt.purpose_id
            and result.policy_id == attempt.policy_id
            and result.policy_version == attempt.policy_version
            and result.policy_digest == attempt.policy_digest
            and result.accessor_id == attempt.approved_accessor_id
            and result.accessor_version == attempt.approved_accessor_version
            and result.runtime_handle_profile_id == attempt.runtime_handle_profile_id
            and result.runtime_handle_profile_version == attempt.runtime_handle_profile_version
            and result.runtime_handle_profile_digest == attempt.runtime_handle_profile_digest
            and result.access_deadline == attempt.access_deadline
            and result.protected_resident_context_usable_until
            == attempt.protected_resident_context_usable_until
            and result.recorded_at <= observed_at
            and (result.completed_at is None or result.completed_at <= result.recorded_at)
            and request.expected_claim_digest == claim.canonical_digest
            and request.expected_attempt_digest == attempt.canonical_digest
            and (
                receipt is None
                or (
                    receipt.access_id == result.access_id == attempt.access_id
                    and receipt.attempt_id == attempt.attempt_id
                    and receipt.consumption_claim_id == claim.claim_id
                    and receipt.instruction_digest == instruction.canonical_digest
                    and receipt.authorization_lease_id == claim.authorization_lease_id
                    and receipt.authorization_lease_digest == result.authorization_lease_digest
                    and receipt.protected_resident_context_id == claim.protected_resident_context_id
                    and receipt.protected_resident_context_digest
                    == result.protected_resident_context_digest
                    and receipt.accessor_contract_id == attempt.required_accessor_contract_id
                    and receipt.accessor_contract_version
                    == attempt.required_accessor_contract_version
                    and receipt.accessor_id == result.accessor_id
                    and receipt.accessor_version == result.accessor_version
                    and receipt.destination_boundary_id == attempt.destination_boundary_id
                    and receipt.destination_deployment_id == attempt.destination_deployment_id
                    and receipt.destination_generation == attempt.destination_generation
                    and receipt.destination_fencing_token_digest
                    == attempt.destination_fencing_token_digest
                    and receipt.runtime_handle_profile_id == result.runtime_handle_profile_id
                    and receipt.runtime_handle_profile_version
                    == result.runtime_handle_profile_version
                    and receipt.runtime_handle_profile_digest
                    == result.runtime_handle_profile_digest
                    and result.accessor_receipt_digest == receipt.canonical_digest
                    and receipt.state is result.state
                    and receipt.failure_class is result.failure_class
                    and receipt.protected_runtime_handle_id == result.protected_runtime_handle_id
                    and receipt.protected_runtime_handle_digest
                    == result.protected_runtime_handle_digest
                    and receipt.protected_runtime_handle_created_at
                    == result.protected_runtime_handle_created_at
                    and receipt.protected_runtime_handle_usable_until
                    == result.protected_runtime_handle_usable_until
                    and receipt.protected_runtime_handle_is_bearer_capability
                    is result.protected_runtime_handle_is_bearer_capability
                    and receipt.protected_resident_context_consumed
                    is result.protected_resident_context_consumed
                    and receipt.runtime_handle_established_in_protected_boundary
                    is result.runtime_handle_established_in_protected_boundary
                    and receipt.runtime_handle_absence_confirmed
                    is result.runtime_handle_absence_confirmed
                    and receipt.completed_at == result.completed_at
                    and receipt.access_deadline == result.access_deadline
                    and receipt.protected_resident_context_usable_until
                    == result.protected_resident_context_usable_until
                    and receipt.signing_key_id == attempt.verification_signing_key_id
                    and attempt.started_at <= receipt.completed_at
                    and receipt.completed_at <= result.recorded_at
                    and receipt.completed_at < attempt.access_deadline
                )
            )
            and self._protected_resident_context_access_consumption_authority_is_zero(
                result.authority
            )
        )

    @staticmethod
    def _protected_resident_context_access_consumption_contract_violation() -> NoReturn:
        raise WorkflowProtectedResidentContextAccessConsumptionError(
            "protected_resident_context_access_consumption_repository_contract_violation"
        )

    async def _lock_protected_resident_context_access_authorization_sources(
        self,
        session: AsyncSession,
        *,
        request: Any,
    ) -> _ProtectedResidentContextAccessAuthorizationLockedSources:
        first_observed_at = cast(datetime, await session.scalar(select(func.clock_timestamp())))
        source = request.source
        opening_authorization_lease = await session.get(
            WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationLeaseModel,
            source.authorization_lease.authorization_lease_id,
            with_for_update=True,
        )
        opening_authorization_claim = cast(
            WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationClaimModel | None,
            await session.scalar(
                select(WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationClaimModel)
                .where(
                    WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationClaimModel.authorization_lease_id
                    == source.authorization_lease.authorization_lease_id
                )
                .with_for_update()
            ),
        )
        opening_claim = cast(
            WorkflowProtectedTransportTargetContextCapsuleOpeningConsumptionClaimModel | None,
            await session.scalar(
                select(WorkflowProtectedTransportTargetContextCapsuleOpeningConsumptionClaimModel)
                .where(
                    WorkflowProtectedTransportTargetContextCapsuleOpeningConsumptionClaimModel.claim_id
                    == source.consumption_claim.claim_id
                )
                .with_for_update()
            ),
        )
        opening_attempt = cast(
            WorkflowProtectedTransportTargetContextCapsuleOpeningAttemptModel | None,
            await session.scalar(
                select(WorkflowProtectedTransportTargetContextCapsuleOpeningAttemptModel)
                .where(
                    WorkflowProtectedTransportTargetContextCapsuleOpeningAttemptModel.attempt_id
                    == source.attempt.attempt_id
                )
                .with_for_update()
            ),
        )
        opening_result = cast(
            WorkflowProtectedTransportTargetContextCapsuleOpeningResultModel | None,
            await session.scalar(
                select(WorkflowProtectedTransportTargetContextCapsuleOpeningResultModel)
                .where(
                    WorkflowProtectedTransportTargetContextCapsuleOpeningResultModel.opening_id
                    == source.result.opening_id
                )
                .with_for_update()
            ),
        )
        existing_leases = tuple(
            (
                await session.scalars(
                    select(WorkflowProtectedResidentContextAccessAuthorizationLeaseModel)
                    .where(
                        or_(
                            WorkflowProtectedResidentContextAccessAuthorizationLeaseModel.opening_id
                            == source.result.opening_id,
                            WorkflowProtectedResidentContextAccessAuthorizationLeaseModel.protected_resident_context_id
                            == source.protected_resident_context_id,
                        )
                    )
                    .with_for_update()
                )
            ).all()
        )
        idempotency_scope_id = self._protected_resident_context_access_idempotency_scope(
            request.scope, request.consumer_subject_id, request.consumer_audience
        )
        idempotency_claim = cast(
            WorkflowProtectedResidentContextAccessAuthorizationClaimModel | None,
            await session.scalar(
                select(WorkflowProtectedResidentContextAccessAuthorizationClaimModel)
                .where(
                    WorkflowProtectedResidentContextAccessAuthorizationClaimModel.idempotency_scope_id
                    == idempotency_scope_id,
                    WorkflowProtectedResidentContextAccessAuthorizationClaimModel.idempotency_key
                    == request.idempotency_digest,
                )
                .with_for_update()
            ),
        )
        observed_at = cast(datetime, await session.scalar(select(func.clock_timestamp())))
        return _ProtectedResidentContextAccessAuthorizationLockedSources(
            opening_authorization_lease=opening_authorization_lease,
            opening_authorization_claim=opening_authorization_claim,
            opening_claim=opening_claim,
            opening_attempt=opening_attempt,
            opening_result=opening_result,
            existing_leases=existing_leases,
            idempotency_claim=idempotency_claim,
            first_observed_at=first_observed_at,
            observed_at=observed_at,
        )

    @classmethod
    def _protected_resident_context_access_evidence_matches(
        cls,
        *,
        request: Any,
        locked: _ProtectedResidentContextAccessAuthorizationLockedSources,
    ) -> bool:
        claim_row = locked.opening_claim
        attempt_row = locked.opening_attempt
        result_row = locked.opening_result
        if claim_row is None or attempt_row is None or result_row is None:
            return False
        source = request.source
        candidate = request.candidate
        attestation = request.lifecycle_attestation
        try:
            result = cls._target_context_capsule_opening_result_from_row(result_row)
            attempt = cls._target_context_capsule_opening_attempt_from_row(attempt_row)
            claim = cls._target_context_capsule_opening_consumption_claim_from_row(claim_row)
            signature_valid = request.offline_signature_verifier.verify_lifecycle_attestation(
                attestation
            )
        except Exception:
            return False
        state = getattr(result.state, "value", result.state)
        return bool(
            locked.first_observed_at <= locked.observed_at
            and source.result == result
            and source.attempt == attempt
            and source.consumption_claim == claim
            and state == "opened_in_protected_consumer_boundary"
            and result.failure_class is None
            and result.opening_receipt_digest is not None
            and result.protected_resident_context_id is not None
            and result.protected_resident_context_digest is not None
            and result.protected_resident_context_created_at == result.completed_at
            and result.completed_at is not None
            and result.completed_at < result.opening_deadline
            and result.protected_resident_context_usable_until is not None
            and locked.observed_at < result.protected_resident_context_usable_until
            and result.protected_resident_context_is_bearer_capability is False
            and result.capsule_opened_in_protected_boundary is True
            and result.target_context_pair_verified is True
            and result.outcome_known is True
            and result.protected_source_closed is True
            and result.source_capsule_zeroized is True
            and candidate.opening_id == result.opening_id
            and candidate.opening_result_digest == result.canonical_digest
            and candidate.opening_attempt_id == attempt.attempt_id
            and candidate.opening_attempt_digest == attempt.canonical_digest
            and candidate.opening_consumption_claim_id == claim.claim_id
            and candidate.opening_consumption_claim_digest == claim.canonical_digest
            and candidate.opening_receipt_digest == result.opening_receipt_digest
            and candidate.protected_resident_context_id == result.protected_resident_context_id
            and candidate.protected_resident_context_digest
            == result.protected_resident_context_digest
            and candidate.protected_resident_context_created_at
            == result.protected_resident_context_created_at
            and candidate.protected_resident_context_usable_until
            == result.protected_resident_context_usable_until
            and candidate.scope == request.scope == result.scope
            and candidate.consumer_subject_id == request.consumer_subject_id
            and candidate.consumer_audience == request.consumer_audience
            and candidate.valid_until > candidate.issued_at
            and candidate.valid_until <= candidate.issued_at + timedelta(seconds=1)
            and candidate.valid_until <= candidate.effective_until
            and candidate.effective_until <= result.protected_resident_context_usable_until
            and candidate.effective_until <= attestation.valid_until
            and attestation.observed_at <= locked.observed_at < attestation.valid_until
            and attestation.request_nonce_digest == request.expected_request_nonce_digest
            and attestation.opening_id == result.opening_id
            and attestation.opening_result_digest == result.canonical_digest
            and attestation.protected_resident_context_id == result.protected_resident_context_id
            and attestation.protected_resident_context_digest
            == result.protected_resident_context_digest
            and attestation.resident_context_present is True
            and attestation.resident_context_is_bearer_capability is False
            and attestation.resident_context_unexpired is True
            and attestation.resident_context_unrevoked is True
            and attestation.resident_context_undestroyed is True
            and attestation.resident_context_unconsumed is True
            and attestation.resident_context_handle_outstanding is False
            and signature_valid is True
            and candidate.protected_resident_context_access_authority_granted is True
            and all(
                getattr(candidate, name) is False
                for name in candidate.__dataclass_fields__
                if name.endswith("_authorized")
            )
        )

    @staticmethod
    def _protected_resident_context_access_retimed_request(
        request: WorkflowProtectedResidentContextAccessAuthorizationLeaseRequest,
        *,
        issued_at: datetime,
    ) -> WorkflowProtectedResidentContextAccessAuthorizationLeaseRequest:
        effective_until = min(
            request.candidate.protected_resident_context_usable_until,
            request.lifecycle_attestation.valid_until,
        )
        valid_until = min(issued_at + timedelta(seconds=1), effective_until)
        payload = request.candidate.digest_payload()
        payload["issued_at"] = issued_at.isoformat()
        payload["valid_until"] = valid_until.isoformat()
        payload["effective_until"] = effective_until.isoformat()
        candidate = dataclass_replace(
            request.candidate,
            issued_at=issued_at,
            valid_until=valid_until,
            effective_until=effective_until,
            canonical_digest=canonical_digest(payload),
        )
        return dataclass_replace(request, requested_at=issued_at, candidate=candidate)

    @classmethod
    def _protected_resident_context_access_replay(
        cls,
        *,
        request: WorkflowProtectedResidentContextAccessAuthorizationLeaseRequest,
        locked: _ProtectedResidentContextAccessAuthorizationLockedSources,
    ) -> WorkflowProtectedResidentContextAccessAuthorizationLeaseResult | None:
        statuses = WorkflowProtectedResidentContextAccessAuthorizationLeaseStatus
        claim = locked.idempotency_claim
        if claim is None:
            return None
        if (
            claim.request_fingerprint != request.request_fingerprint
            or claim.opening_id != request.source.result.opening_id
            or claim.protected_resident_context_id
            != request.source.result.protected_resident_context_id
        ):
            return WorkflowProtectedResidentContextAccessAuthorizationLeaseResult(
                statuses.IDEMPOTENCY_CONFLICT, None
            )
        row = next(
            (
                item
                for item in locked.existing_leases
                if item.access_authorization_lease_id == claim.access_authorization_lease_id
            ),
            None,
        )
        if row is None:
            return WorkflowProtectedResidentContextAccessAuthorizationLeaseResult(
                statuses.EVIDENCE_CONFLICT, None
            )
        return WorkflowProtectedResidentContextAccessAuthorizationLeaseResult(
            statuses.REPLAY,
            cls._resident_context_access_lease_from_row(row),
            locked.observed_at,
        )

    @staticmethod
    def _protected_resident_context_access_idempotency_scope(
        scope: WorkflowScope,
        subject_id: str,
        audience: str,
    ) -> str:
        return canonical_digest(
            {
                "scope": scope.canonical_value(),
                "subject_id": subject_id,
                "audience": audience,
            }
        )

    @staticmethod
    def _resident_context_access_authority_columns(value: Any) -> dict[str, bool]:
        columns = {
            name.replace("_authorized", "_authority_granted"): getattr(value, name)
            for name in value.__dataclass_fields__
            if name.endswith("_authorized")
        }
        columns["protected_resident_context_access_authority_granted"] = (
            value.protected_resident_context_access_authority_granted
        )
        return columns

    @classmethod
    def _resident_context_access_lease_model(
        cls,
        *,
        lease: WorkflowProtectedResidentContextAccessAuthorizationLease,
        claim: WorkflowProtectedResidentContextAccessAuthorizationClaim,
        attestation: Any,
    ) -> WorkflowProtectedResidentContextAccessAuthorizationLeaseModel:
        scalars = {
            name: getattr(lease, name)
            for name in lease.__dataclass_fields__
            if name
            not in {
                "authorization_lease_id",
                "scope",
                "state",
                "canonical_digest",
            }
            and not name.endswith("_authorized")
            and name != "protected_resident_context_access_authority_granted"
        }
        return WorkflowProtectedResidentContextAccessAuthorizationLeaseModel(
            access_authorization_lease_id=lease.authorization_lease_id,
            **scalars,
            organization_id=lease.scope.organization_id,
            environment_id=lease.scope.environment_id,
            site_id=lease.scope.site_id,
            destination_boundary_id=attestation.destination_boundary_id,
            destination_deployment_id=attestation.destination_deployment_id,
            destination_generation=attestation.destination_generation,
            destination_fencing_token_digest=attestation.destination_fencing_token_digest,
            lifecycle_attestor_id=attestation.attestor_id,
            lifecycle_attestor_version=attestation.attestor_version,
            lifecycle_signing_key_id=attestation.signing_key_id,
            lifecycle_profile_digest=canonical_digest(
                {
                    "attestor_id": attestation.attestor_id,
                    "attestor_version": attestation.attestor_version,
                    "signing_key_id": attestation.signing_key_id,
                }
            ),
            request_nonce_digest=attestation.request_nonce_digest,
            resident_context_present=attestation.resident_context_present,
            resident_context_unexpired=attestation.resident_context_unexpired,
            resident_context_unrevoked=attestation.resident_context_unrevoked,
            resident_context_undestroyed=attestation.resident_context_undestroyed,
            resident_context_unconsumed=attestation.resident_context_unconsumed,
            resident_context_handle_outstanding=(attestation.resident_context_handle_outstanding),
            state=lease.state.value,
            **cls._resident_context_access_authority_columns(lease),
            canonical_digest=lease.canonical_digest,
            payload=lease.digest_payload(),
            lifecycle_attestation_payload=attestation.digest_payload(),
        )

    @classmethod
    def _resident_context_access_claim_model(
        cls,
        *,
        claim: WorkflowProtectedResidentContextAccessAuthorizationClaim,
        authorization_lease_id: str,
        audit_payload: dict[str, object],
    ) -> WorkflowProtectedResidentContextAccessAuthorizationClaimModel:
        scalars = {
            name: getattr(claim, name)
            for name in claim.__dataclass_fields__
            if name not in {"scope", "canonical_digest"}
            and not name.endswith("_authorized")
            and name != "protected_resident_context_access_authority_granted"
        }
        return WorkflowProtectedResidentContextAccessAuthorizationClaimModel(
            access_authorization_lease_id=authorization_lease_id,
            **scalars,
            organization_id=claim.scope.organization_id,
            environment_id=claim.scope.environment_id,
            site_id=claim.scope.site_id,
            idempotency_scope_id=cls._protected_resident_context_access_idempotency_scope(
                claim.scope, claim.consumer_subject_id, claim.consumer_audience
            ),
            idempotency_key=claim.idempotency_digest,
            **cls._resident_context_access_authority_columns(claim),
            canonical_digest=claim.canonical_digest,
            payload=claim.digest_payload(),
            authorization_audit_payload=audit_payload,
        )

    @staticmethod
    def _resident_context_access_lease_from_row(
        row: WorkflowProtectedResidentContextAccessAuthorizationLeaseModel,
    ) -> WorkflowProtectedResidentContextAccessAuthorizationLease:
        payload = dict(row.payload)
        payload["scope"] = WorkflowScope(**cast(dict[str, str], payload["scope"]))
        payload["state"] = WorkflowProtectedResidentContextAccessAuthorizationLeaseState(
            str(payload["state"])
        )
        payload["opening_result_state"] = (
            WorkflowProtectedTransportTargetContextCapsuleOpeningResultState(
                str(payload["opening_result_state"])
            )
        )
        for name in (
            "opening_completed_at",
            "opening_deadline",
            "protected_resident_context_created_at",
            "protected_resident_context_usable_until",
            "lifecycle_attestation_valid_until",
            "issued_at",
            "valid_until",
            "effective_until",
        ):
            payload[name] = datetime.fromisoformat(str(payload[name]))
        return WorkflowProtectedResidentContextAccessAuthorizationLease(
            **cast(Any, payload), canonical_digest=row.canonical_digest
        )

    @staticmethod
    def _resident_context_access_opening_receipt_from_row(
        row: WorkflowProtectedTransportTargetContextCapsuleOpeningResultModel,
    ) -> WorkflowProtectedTransportTargetContextCapsuleTrustedOpenerReceipt:
        if row.opening_receipt_payload is None:
            raise ValueError("opening receipt payload is absent")
        payload = dict(row.opening_receipt_payload)
        digest = str(payload.pop("canonical_digest"))
        payload["state"] = WorkflowProtectedTransportTargetContextCapsuleOpeningResultState(
            str(payload["state"])
        )
        if payload["failure_class"] is not None:
            payload["failure_class"] = (
                WorkflowProtectedTransportTargetContextCapsuleOpeningFailureClass(
                    str(payload["failure_class"])
                )
            )
        for name in (
            "completed_at",
            "opening_deadline",
            "protected_resident_context_created_at",
            "protected_resident_context_usable_until",
        ):
            if payload[name] is not None:
                payload[name] = datetime.fromisoformat(str(payload[name]))
        return WorkflowProtectedTransportTargetContextCapsuleTrustedOpenerReceipt(
            **cast(Any, payload), canonical_digest=digest
        )

    @staticmethod
    async def _publish_protected_resident_context_access_audit(
        *,
        request: Any,
        audit_payload: dict[str, object],
    ) -> None:
        publisher = getattr(request, "publish_committed_audit", None)
        if publisher is None:
            return
        try:
            await publisher(audit_payload)
        except Exception:
            return

    async def _lock_target_context_capsule_opening_authorization_sources(
        self,
        session: AsyncSession,
        *,
        request: WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationLeaseRequest,
    ) -> _TargetContextCapsuleOpeningAuthorizationLockedSources:
        result_row = cast(
            WorkflowProtectedTransportTargetContextCapsuleHandoffResultModel | None,
            await session.scalar(
                select(WorkflowProtectedTransportTargetContextCapsuleHandoffResultModel)
                .where(
                    WorkflowProtectedTransportTargetContextCapsuleHandoffResultModel.handoff_id
                    == request.source.result.handoff_id
                )
                .with_for_update()
            ),
        )
        attempt_row = claim_row = upstream_lease_row = upstream_claim_row = None
        binding_row = binding_claim_row = binding_sources = None
        if result_row is not None:
            attempt_row = cast(
                WorkflowProtectedTransportTargetContextCapsuleHandoffAttemptModel | None,
                await session.scalar(
                    select(WorkflowProtectedTransportTargetContextCapsuleHandoffAttemptModel)
                    .where(
                        WorkflowProtectedTransportTargetContextCapsuleHandoffAttemptModel.attempt_id
                        == result_row.attempt_id
                    )
                    .with_for_update()
                ),
            )
            claim_row = cast(
                WorkflowProtectedTransportTargetContextCapsuleHandoffConsumptionClaimModel | None,
                await session.scalar(
                    select(
                        WorkflowProtectedTransportTargetContextCapsuleHandoffConsumptionClaimModel
                    )
                    .where(
                        WorkflowProtectedTransportTargetContextCapsuleHandoffConsumptionClaimModel.claim_id
                        == result_row.consumption_claim_id
                    )
                    .with_for_update()
                ),
            )
            upstream_lease_row = cast(
                WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseModel | None,
                await session.scalar(
                    select(
                        WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseModel
                    )
                    .where(
                        WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseModel.authorization_lease_id
                        == result_row.authorization_lease_id
                    )
                    .with_for_update()
                ),
            )
            upstream_claim_row = cast(
                WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationClaimModel | None,
                await session.scalar(
                    select(
                        WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationClaimModel
                    )
                    .where(
                        WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationClaimModel.authorization_lease_id
                        == result_row.authorization_lease_id
                    )
                    .with_for_update()
                ),
            )
            binding_row = await session.get(
                WorkflowProtectedTransportTargetContextCapsuleConsumerBindingModel,
                result_row.consumer_binding_id,
                with_for_update=True,
            )
            if binding_row is not None:
                binding_claim_row = cast(
                    WorkflowProtectedTransportTargetContextCapsuleConsumerBindingClaimModel | None,
                    await session.scalar(
                        select(
                            WorkflowProtectedTransportTargetContextCapsuleConsumerBindingClaimModel
                        )
                        .where(
                            WorkflowProtectedTransportTargetContextCapsuleConsumerBindingClaimModel.binding_id
                            == binding_row.binding_id
                        )
                        .with_for_update()
                    ),
                )
            if binding_row is not None and binding_claim_row is not None:
                binding_sources = await self._lock_target_context_capsule_consumer_binding_sources(
                    session,
                    request=self._target_context_capsule_handoff_binding_request(
                        binding_row,
                        binding_claim_row,
                        requested_at=request.requested_at,
                    ),
                )
        source = self._target_context_capsule_opening_source_from_rows(
            result_row=result_row,
            attempt_row=attempt_row,
            consumption_claim_row=claim_row,
            upstream_lease_row=upstream_lease_row,
            upstream_claim_row=upstream_claim_row,
            binding_row=binding_row,
            binding_claim_row=binding_claim_row,
        )
        existing_leases: tuple[
            WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationLeaseModel, ...
        ] = ()
        if source is not None:
            existing_leases = tuple(
                (
                    await session.scalars(
                        select(
                            WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationLeaseModel
                        )
                        .where(
                            or_(
                                WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationLeaseModel.handoff_id
                                == source.result.handoff_id,
                                WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationLeaseModel.consumer_receipt_id
                                == source.result.consumer_receipt_id,
                                WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationLeaseModel.sealed_capsule_id
                                == source.attempt.sealed_capsule_id,
                            )
                        )
                        .with_for_update()
                    )
                ).all()
            )
        scope_id = self._target_context_capsule_opening_idempotency_scope(
            request.scope, request.consumer_subject_id, request.consumer_audience
        )
        idempotency_claim = cast(
            WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationClaimModel | None,
            await session.scalar(
                select(WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationClaimModel)
                .where(
                    WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationClaimModel.idempotency_scope_id
                    == scope_id,
                    WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationClaimModel.idempotency_key
                    == request.idempotency_key,
                )
                .with_for_update()
            ),
        )
        observed_at = cast(datetime, await session.scalar(select(func.clock_timestamp())))
        return _TargetContextCapsuleOpeningAuthorizationLockedSources(
            source=source,
            result_row=result_row,
            attempt_row=attempt_row,
            consumption_claim_row=claim_row,
            upstream_lease_row=upstream_lease_row,
            upstream_claim_row=upstream_claim_row,
            binding_sources=binding_sources,
            existing_leases=existing_leases,
            idempotency_claim=idempotency_claim,
            observed_at=observed_at,
        )

    @classmethod
    def _target_context_capsule_opening_source_from_rows(
        cls,
        *,
        result_row: WorkflowProtectedTransportTargetContextCapsuleHandoffResultModel | None,
        attempt_row: WorkflowProtectedTransportTargetContextCapsuleHandoffAttemptModel | None,
        consumption_claim_row: (
            WorkflowProtectedTransportTargetContextCapsuleHandoffConsumptionClaimModel | None
        ),
        upstream_lease_row: (
            WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseModel | None
        ),
        upstream_claim_row: (
            WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationClaimModel | None
        ),
        binding_row: WorkflowProtectedTransportTargetContextCapsuleConsumerBindingModel | None,
        binding_claim_row: WorkflowProtectedTransportTargetContextCapsuleConsumerBindingClaimModel
        | None,
    ) -> WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationSource | None:
        if any(
            row is None
            for row in (
                result_row,
                attempt_row,
                consumption_claim_row,
                upstream_lease_row,
                upstream_claim_row,
                binding_row,
                binding_claim_row,
            )
        ):
            return None
        assert result_row is not None
        assert attempt_row is not None
        assert consumption_claim_row is not None
        assert upstream_lease_row is not None
        assert upstream_claim_row is not None
        assert binding_row is not None
        assert binding_claim_row is not None
        try:
            return WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationSource(
                result=cls._target_context_capsule_handoff_result_from_row(result_row),
                attempt=cls._target_context_capsule_handoff_attempt_from_row(attempt_row),
                consumption_claim=cls._target_context_capsule_handoff_consumption_claim_from_row(
                    consumption_claim_row
                ),
                upstream_authorization_lease=cls._target_context_capsule_handoff_lease_from_claim(
                    upstream_claim_row, upstream_lease_row
                ),
                consumer_binding=cls._target_context_capsule_consumer_binding_from_claim(
                    binding_claim_row, binding_row=binding_row
                ),
            )
        except Exception:
            return None

    @classmethod
    def _target_context_capsule_opening_evidence_matches(
        cls,
        *,
        request: WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationLeaseRequest,
        locked: _TargetContextCapsuleOpeningAuthorizationLockedSources,
    ) -> bool:
        source = locked.source
        if source is None or locked.binding_sources is None:
            return False
        try:
            validate_workflow_protected_transport_target_context_capsule_opening_authorization_request(
                request
            )
            binding_row = locked.binding_sources.existing_bindings
            binding_model = next(
                (
                    row
                    for row in binding_row
                    if row.binding_id == source.consumer_binding.binding_id
                ),
                None,
            )
            current = dataclass_replace(locked.binding_sources, observed_at=locked.observed_at)
            binding_request = cls._target_context_capsule_handoff_binding_request(
                cast(
                    WorkflowProtectedTransportTargetContextCapsuleConsumerBindingModel,
                    binding_model,
                ),
                cast(
                    WorkflowProtectedTransportTargetContextCapsuleConsumerBindingClaimModel,
                    locked.binding_sources.idempotency_claim,
                ),
                requested_at=locked.observed_at,
            )
            upstream_evidence = cls._target_context_capsule_consumer_binding_evidence(
                current, request=binding_request
            )
            attestation = request.custody_attestation
            policy = _opening_authorization_policy()
            signature_valid = (
                request.offline_signature_verifier.verify_destination_custody_attestation(
                    attestation
                )
            )
        except Exception:
            return False
        return bool(
            upstream_evidence is not None
            and signature_valid
            and source == request.source
            and source.result.state
            is WorkflowProtectedTransportTargetContextCapsuleHandoffResultState.HANDED_OFF_SEALED
            and source.result.consumer_receipt_id is not None
            and not source.result.consumer_receipt_is_bearer_capability
            and source.result.sealed_capsule_handed_off
            and source.result.usable_until is not None
            and locked.observed_at < source.result.usable_until
            and source.attempt.destination_boundary_id == policy.destination_boundary_id
            and source.attempt.destination_deployment_id == policy.destination_deployment_id
            and source.attempt.destination_generation == policy.destination_generation
            and source.attempt.destination_fencing_token_digest
            == policy.destination_fencing_token_digest
            and source.attempt.custody_contract_id == policy.custody_contract_id
            and source.attempt.custody_contract_version == policy.custody_contract_version
            and source.attempt.approved_adapter_id == policy.approved_adapter_id
            and source.attempt.approved_adapter_version == policy.approved_adapter_version
            and source.attempt.verification_signing_key_id == policy.verification_signing_key_id
            and source.attempt.trusted_profile_digest == policy.trusted_profile_digest
            and attestation.attestor_id == policy.required_attestor_id
            and attestation.attestor_version == policy.required_attestor_version
            and attestation.observed_at <= locked.observed_at
            and request.candidate.valid_until <= attestation.valid_until
            and request.candidate.valid_until <= source.result.usable_until
            and request.candidate.issued_at <= locked.observed_at
            and request.candidate.valid_until - request.candidate.issued_at == timedelta(seconds=1)
        )

    @staticmethod
    def _target_context_capsule_opening_retimed_request(
        request: WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationLeaseRequest,
        *,
        issued_at: datetime,
    ) -> WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationLeaseRequest:
        valid_until = issued_at + timedelta(seconds=1)
        payload = request.candidate.digest_payload()
        payload["issued_at"] = issued_at.isoformat()
        payload["valid_until"] = valid_until.isoformat()
        candidate = dataclass_replace(
            request.candidate,
            issued_at=issued_at,
            valid_until=valid_until,
            canonical_digest=canonical_digest(payload),
        )
        return dataclass_replace(request, requested_at=issued_at, candidate=candidate)

    @classmethod
    def _target_context_capsule_opening_replay(
        cls,
        *,
        request: WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationLeaseRequest,
        locked: _TargetContextCapsuleOpeningAuthorizationLockedSources,
    ) -> WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationLeaseResult | None:
        claim = locked.idempotency_claim
        if claim is None:
            return None
        statuses = WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationLeaseStatus
        if claim.request_fingerprint != request.request_fingerprint:
            return WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationLeaseResult(
                statuses.IDEMPOTENCY_CONFLICT, None
            )
        row = next(
            (
                item
                for item in locked.existing_leases
                if item.authorization_lease_id == claim.authorization_lease_id
            ),
            None,
        )
        if row is None:
            return WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationLeaseResult(
                statuses.EVIDENCE_CONFLICT, None
            )
        return WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationLeaseResult(
            statuses.REPLAY,
            cls._target_context_capsule_opening_lease_from_row(row),
            locked.observed_at,
        )

    @staticmethod
    def _target_context_capsule_opening_idempotency_scope(
        scope: WorkflowScope, subject_id: str, audience: str
    ) -> str:
        return canonical_digest(
            {
                "scope": scope.canonical_value(),
                "subject_id": subject_id,
                "audience": audience,
            }
        )

    @staticmethod
    def _target_context_capsule_opening_authority_columns(
        authority: WorkflowProtectedTransportTargetContextCapsuleOpeningLeaseAuthority,
    ) -> dict[str, bool]:
        return {
            name.replace("_authorized", "_authority_granted"): value
            for name, value in authority.canonical_value().items()
        }

    @classmethod
    def _target_context_capsule_opening_lease_model(
        cls,
        request: WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationLeaseRequest,
    ) -> WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationLeaseModel:
        lease = request.candidate
        return WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationLeaseModel(
            **{
                name: getattr(lease, name)
                for name in lease.__dataclass_fields__
                if name not in {"scope", "state", "authority", "canonical_digest"}
            },
            organization_id=lease.scope.organization_id,
            environment_id=lease.scope.environment_id,
            site_id=lease.scope.site_id,
            state=lease.state.value,
            **cls._target_context_capsule_opening_authority_columns(lease.authority),
            canonical_digest=lease.canonical_digest,
            payload=lease.digest_payload(),
            custody_attestation_payload=request.custody_attestation.digest_payload(),
        )

    @classmethod
    def _target_context_capsule_opening_claim_model(
        cls,
        request: WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationLeaseRequest,
        *,
        audit_payload: dict[str, object],
        claimed_at: datetime,
    ) -> WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationClaimModel:
        lease = request.candidate
        audit_digest = canonical_digest(audit_payload)
        payload: dict[str, object] = {
            "authorization_lease_id": lease.authorization_lease_id,
            "handoff_id": lease.handoff_id,
            "consumer_receipt_id": lease.consumer_receipt_id,
            "sealed_capsule_id": lease.sealed_capsule_id,
            "scope": lease.scope.canonical_value(),
            "consumer_subject_id": request.consumer_subject_id,
            "consumer_audience": request.consumer_audience,
            "request_fingerprint": request.request_fingerprint,
            "authorization_audit_digest": audit_digest,
            "claimed_at": claimed_at.isoformat(),
        }
        digest = canonical_digest(payload)
        return WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationClaimModel(
            claim_id=f"workflow-target-context-capsule-opening-authorization-claim.{digest[:24]}",
            authorization_lease_id=lease.authorization_lease_id,
            handoff_id=lease.handoff_id,
            consumer_receipt_id=lease.consumer_receipt_id,
            sealed_capsule_id=lease.sealed_capsule_id,
            organization_id=lease.scope.organization_id,
            environment_id=lease.scope.environment_id,
            site_id=lease.scope.site_id,
            consumer_subject_id=request.consumer_subject_id,
            consumer_audience=request.consumer_audience,
            idempotency_scope_id=cls._target_context_capsule_opening_idempotency_scope(
                request.scope, request.consumer_subject_id, request.consumer_audience
            ),
            idempotency_key=request.idempotency_key,
            request_fingerprint=request.request_fingerprint,
            authorization_audit_digest=audit_digest,
            claimed_at=claimed_at,
            canonical_digest=digest,
            payload=payload,
            authorization_audit_payload=audit_payload,
        )

    @staticmethod
    def _target_context_capsule_opening_lease_from_row(
        row: WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationLeaseModel,
    ) -> WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationLease:
        payload = dict(row.payload)
        payload["scope"] = WorkflowScope(**cast(dict[str, str], payload["scope"]))
        payload["state"] = (
            WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationLeaseState(
                str(payload["state"])
            )
        )
        payload["authority"] = WorkflowProtectedTransportTargetContextCapsuleOpeningLeaseAuthority(
            **cast(dict[str, bool], payload["authority"])
        )
        for name in (
            "custody_attestation_valid_until",
            "issued_at",
            "valid_until",
            "effective_until",
        ):
            payload[name] = datetime.fromisoformat(str(payload[name]))
        return WorkflowProtectedTransportTargetContextCapsuleOpeningAuthorizationLease(
            **cast(Any, payload), canonical_digest=row.canonical_digest
        )

    async def get_target_context_capsule_handoff_authorization_lease_by_id(
        self,
        *,
        authorization_lease_id: str,
    ) -> WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLease | None:
        async with self._sessions() as session:
            row = await session.get(
                WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseModel,
                authorization_lease_id,
            )
            claim = (
                None
                if row is None
                else cast(
                    WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationClaimModel
                    | None,
                    await session.scalar(
                        select(
                            WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationClaimModel
                        ).where(
                            WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationClaimModel.authorization_lease_id
                            == row.authorization_lease_id
                        )
                    ),
                )
            )
        return (
            None
            if row is None
            else self._target_context_capsule_handoff_lease_from_claim(claim, row)
        )

    async def lookup_target_context_capsule_handoff_replay(
        self, request: WorkflowTargetContextCapsuleHandoffReplayLookupRequest
    ) -> WorkflowTargetContextCapsuleHandoffReplayLookup:
        statuses = WorkflowProtectedTransportTargetContextCapsuleHandoffReplayStatus
        scope_id = self._target_context_capsule_handoff_consumption_idempotency_scope(
            request.scope, request.consumer_subject_id, request.consumer_audience
        )
        async with self._sessions() as session:
            rows = tuple(
                (
                    await session.scalars(
                        select(
                            WorkflowProtectedTransportTargetContextCapsuleHandoffConsumptionClaimModel
                        ).where(
                            WorkflowProtectedTransportTargetContextCapsuleHandoffConsumptionClaimModel.organization_id
                            == request.scope.organization_id,
                            WorkflowProtectedTransportTargetContextCapsuleHandoffConsumptionClaimModel.environment_id
                            == request.scope.environment_id,
                            WorkflowProtectedTransportTargetContextCapsuleHandoffConsumptionClaimModel.site_id
                            == request.scope.site_id,
                            or_(
                                and_(
                                    WorkflowProtectedTransportTargetContextCapsuleHandoffConsumptionClaimModel.idempotency_scope_id
                                    == scope_id,
                                    WorkflowProtectedTransportTargetContextCapsuleHandoffConsumptionClaimModel.idempotency_digest
                                    == request.idempotency_digest,
                                ),
                                WorkflowProtectedTransportTargetContextCapsuleHandoffConsumptionClaimModel.authorization_lease_id
                                == request.authorization_lease_id,
                            ),
                        )
                    )
                ).all()
            )
            if not rows:
                return WorkflowTargetContextCapsuleHandoffReplayLookup(statuses.NONE, None, None)
            row = next(
                (
                    value
                    for value in rows
                    if value.idempotency_scope_id == scope_id
                    and value.idempotency_digest == request.idempotency_digest
                ),
                None,
            )
            if row is None:
                return WorkflowTargetContextCapsuleHandoffReplayLookup(
                    statuses.ALREADY_CONSUMED, None, None
                )
            claim = self._target_context_capsule_handoff_consumption_claim_from_row(row)
            attempt_row = cast(
                WorkflowProtectedTransportTargetContextCapsuleHandoffAttemptModel | None,
                await session.scalar(
                    select(WorkflowProtectedTransportTargetContextCapsuleHandoffAttemptModel).where(
                        WorkflowProtectedTransportTargetContextCapsuleHandoffAttemptModel.consumption_claim_id
                        == claim.claim_id
                    )
                ),
            )
            if attempt_row is None:
                self._target_context_capsule_handoff_consumption_contract_violation()
            attempt = self._target_context_capsule_handoff_attempt_from_row(attempt_row)
            if (
                claim.request_fingerprint != request.request_fingerprint
                or claim.authorization_lease_id != request.authorization_lease_id
                or claim.authorization_lease_digest != request.authorization_lease_digest
                or claim.handoff_id != request.handoff_id
                or claim.scope != request.scope
                or claim.consumer_subject_id != request.consumer_subject_id
                or claim.consumer_audience != request.consumer_audience
                or claim.policy_id != request.policy_id
                or claim.policy_version != request.policy_version
                or claim.policy_digest != request.policy_digest
                or attempt.consumption_claim_id != claim.claim_id
                or attempt.consumption_claim_digest != claim.canonical_digest
            ):
                return WorkflowTargetContextCapsuleHandoffReplayLookup(
                    statuses.IDEMPOTENCY_CONFLICT, None, None
                )
            result_row = await session.get(
                WorkflowProtectedTransportTargetContextCapsuleHandoffResultModel,
                attempt.handoff_id,
            )
            if result_row is None:
                return WorkflowTargetContextCapsuleHandoffReplayLookup(
                    statuses.CLAIM_ONLY_UNCERTAIN, attempt, None
                )
            result = self._target_context_capsule_handoff_result_from_row(result_row)
            if (
                result.attempt_id != attempt.attempt_id
                or result.attempt_digest != attempt.canonical_digest
                or result.consumption_claim_id != claim.claim_id
                or result.consumption_claim_digest != claim.canonical_digest
            ):
                self._target_context_capsule_handoff_consumption_contract_violation()
            return WorkflowTargetContextCapsuleHandoffReplayLookup(
                statuses.TERMINAL, attempt, result
            )

    async def claim_target_context_capsule_handoff(
        self, request: WorkflowTargetContextCapsuleHandoffClaimRequest
    ) -> WorkflowTargetContextCapsuleHandoffClaimResult:
        statuses = WorkflowProtectedTransportTargetContextCapsuleHandoffClaimStatus
        async with self._sessions() as session:
            locked = await self._lock_target_context_capsule_handoff_sources(
                session, request=request
            )
            replay = self._target_context_capsule_handoff_locked_replay(
                request=request, locked=locked
            )
            if replay is not None:
                await session.rollback()
                return replay
            if not self._target_context_capsule_handoff_claim_is_valid(
                request=request, locked=locked
            ):
                await session.rollback()
                return WorkflowTargetContextCapsuleHandoffClaimResult(
                    statuses.EVIDENCE_CONFLICT, None, None, None
                )
            commit_at = cast(datetime, await session.scalar(select(func.clock_timestamp())))
            locked = dataclass_replace(locked, observed_at=commit_at)
            if not self._target_context_capsule_handoff_claim_is_valid(
                request=request, locked=locked
            ):
                await session.rollback()
                return WorkflowTargetContextCapsuleHandoffClaimResult(
                    statuses.EVIDENCE_CONFLICT, None, None, None
                )
            deadline = self._target_context_capsule_handoff_deadline(request, locked=locked)
            if deadline is None:
                await session.rollback()
                return WorkflowTargetContextCapsuleHandoffClaimResult(
                    statuses.EVIDENCE_CONFLICT, None, None, None
                )
            claim = self._target_context_capsule_handoff_consumption_claim(
                request, claimed_at=commit_at
            )
            attempt = self._target_context_capsule_handoff_attempt(
                request,
                claim=claim,
                started_at=commit_at,
                handoff_deadline=deadline,
                lease_valid_until=cast(Any, locked.authorization_lease).valid_until,
                binding_effective_until=cast(
                    Any, locked.authorization.consumer_binding
                ).effective_until,
                source_effective_until=cast(datetime, locked.source_deadline),
            )
            try:
                session.add(
                    self._target_context_capsule_handoff_consumption_claim_model(
                        request, claim=claim
                    )
                )
                await session.flush()
                session.add(
                    self._target_context_capsule_handoff_attempt_model(
                        request,
                        attempt=attempt,
                        locked=locked,
                    )
                )
                await session.flush()
                precommit_at = cast(datetime, await session.scalar(select(func.clock_timestamp())))
                if precommit_at >= deadline:
                    await session.rollback()
                    return WorkflowTargetContextCapsuleHandoffClaimResult(
                        statuses.EVIDENCE_CONFLICT, None, None, None
                    )
                await session.commit()
                return WorkflowTargetContextCapsuleHandoffClaimResult(
                    statuses.CLAIMED, claim, attempt, None
                )
            except IntegrityError:
                await session.rollback()
        lookup = await self.lookup_target_context_capsule_handoff_replay(
            WorkflowTargetContextCapsuleHandoffReplayLookupRequest(
                authorization_lease_id=request.authorization_lease_id,
                authorization_lease_digest=request.authorization_lease_digest,
                scope=request.scope,
                consumer_subject_id=request.consumer_subject_id,
                consumer_audience=request.consumer_audience,
                policy_id=request.expected_policy_id,
                policy_version=request.expected_policy_version,
                policy_digest=request.expected_policy_digest,
                idempotency_digest=request.idempotency_digest,
                request_fingerprint=request.request_fingerprint,
                handoff_id=request.handoff_id,
            )
        )
        if (
            lookup.status
            is WorkflowProtectedTransportTargetContextCapsuleHandoffReplayStatus.TERMINAL
        ):
            return WorkflowTargetContextCapsuleHandoffClaimResult(
                statuses.REPLAY_COMPLETED, None, lookup.attempt, lookup.result
            )
        replay_statuses = WorkflowProtectedTransportTargetContextCapsuleHandoffReplayStatus
        if lookup.status is replay_statuses.CLAIM_ONLY_UNCERTAIN:
            return WorkflowTargetContextCapsuleHandoffClaimResult(
                statuses.CLAIM_ONLY_UNCERTAIN, None, lookup.attempt, None
            )
        return WorkflowTargetContextCapsuleHandoffClaimResult(
            statuses.EVIDENCE_CONFLICT, None, None, None
        )

    async def record_target_context_capsule_handoff_result(
        self, request: WorkflowTargetContextCapsuleHandoffResultRequest
    ) -> WorkflowTargetContextCapsuleHandoffResultWrite:
        statuses = WorkflowProtectedTransportTargetContextCapsuleHandoffResultWriteStatus
        result = request.result
        async with self._sessions() as session:
            claim_row = cast(
                WorkflowProtectedTransportTargetContextCapsuleHandoffConsumptionClaimModel | None,
                await session.scalar(
                    select(
                        WorkflowProtectedTransportTargetContextCapsuleHandoffConsumptionClaimModel
                    )
                    .where(
                        WorkflowProtectedTransportTargetContextCapsuleHandoffConsumptionClaimModel.claim_id
                        == result.consumption_claim_id
                    )
                    .with_for_update()
                ),
            )
            attempt_row = cast(
                WorkflowProtectedTransportTargetContextCapsuleHandoffAttemptModel | None,
                await session.scalar(
                    select(WorkflowProtectedTransportTargetContextCapsuleHandoffAttemptModel)
                    .where(
                        WorkflowProtectedTransportTargetContextCapsuleHandoffAttemptModel.attempt_id
                        == result.attempt_id
                    )
                    .with_for_update()
                ),
            )
            existing = cast(
                WorkflowProtectedTransportTargetContextCapsuleHandoffResultModel | None,
                await session.scalar(
                    select(WorkflowProtectedTransportTargetContextCapsuleHandoffResultModel)
                    .where(
                        WorkflowProtectedTransportTargetContextCapsuleHandoffResultModel.handoff_id
                        == result.handoff_id
                    )
                    .with_for_update()
                ),
            )
            if existing is not None:
                stored = self._target_context_capsule_handoff_result_from_row(existing)
                await session.rollback()
                return WorkflowTargetContextCapsuleHandoffResultWrite(
                    statuses.REPLAY
                    if stored.canonical_digest == result.canonical_digest
                    else statuses.CONFLICT,
                    stored if stored.canonical_digest == result.canonical_digest else None,
                )
            if not self._target_context_capsule_handoff_result_matches(
                request=request, claim_row=claim_row, attempt_row=attempt_row
            ):
                await session.rollback()
                return WorkflowTargetContextCapsuleHandoffResultWrite(statuses.CONFLICT, None)
            try:
                session.add(self._target_context_capsule_handoff_result_model(request))
                await session.commit()
                return WorkflowTargetContextCapsuleHandoffResultWrite(statuses.RECORDED, result)
            except IntegrityError:
                await session.rollback()
        async with self._sessions() as session:
            existing = await session.get(
                WorkflowProtectedTransportTargetContextCapsuleHandoffResultModel,
                result.handoff_id,
            )
            if existing is None:
                return WorkflowTargetContextCapsuleHandoffResultWrite(statuses.CONFLICT, None)
            stored = self._target_context_capsule_handoff_result_from_row(existing)
            return WorkflowTargetContextCapsuleHandoffResultWrite(
                statuses.REPLAY
                if stored.canonical_digest == result.canonical_digest
                else statuses.CONFLICT,
                stored if stored.canonical_digest == result.canonical_digest else None,
            )

    async def list_target_context_capsule_handoff_attempts(
        self, *, scope: WorkflowScope, limit: int = 256
    ) -> tuple[WorkflowProtectedTransportTargetContextCapsuleHandoffAttempt, ...]:
        async with self._sessions() as session:
            rows = tuple(
                (
                    await session.scalars(
                        select(WorkflowProtectedTransportTargetContextCapsuleHandoffAttemptModel)
                        .where(
                            WorkflowProtectedTransportTargetContextCapsuleHandoffAttemptModel.organization_id
                            == scope.organization_id,
                            WorkflowProtectedTransportTargetContextCapsuleHandoffAttemptModel.environment_id
                            == scope.environment_id,
                            WorkflowProtectedTransportTargetContextCapsuleHandoffAttemptModel.site_id
                            == scope.site_id,
                        )
                        .order_by(
                            WorkflowProtectedTransportTargetContextCapsuleHandoffAttemptModel.started_at.desc(),
                            WorkflowProtectedTransportTargetContextCapsuleHandoffAttemptModel.attempt_id,
                        )
                        .limit(max(1, min(limit, 1000)))
                    )
                ).all()
            )
        return tuple(self._target_context_capsule_handoff_attempt_from_row(row) for row in rows)

    async def get_target_context_capsule_handoff_results_by_handoff_ids(
        self, *, scope: WorkflowScope, handoff_ids: tuple[str, ...]
    ) -> tuple[WorkflowProtectedTransportTargetContextCapsuleHandoffResult, ...]:
        if not handoff_ids:
            return ()
        async with self._sessions() as session:
            rows = tuple(
                (
                    await session.scalars(
                        select(
                            WorkflowProtectedTransportTargetContextCapsuleHandoffResultModel
                        ).where(
                            WorkflowProtectedTransportTargetContextCapsuleHandoffResultModel.handoff_id.in_(
                                handoff_ids
                            ),
                            WorkflowProtectedTransportTargetContextCapsuleHandoffResultModel.organization_id
                            == scope.organization_id,
                            WorkflowProtectedTransportTargetContextCapsuleHandoffResultModel.environment_id
                            == scope.environment_id,
                            WorkflowProtectedTransportTargetContextCapsuleHandoffResultModel.site_id
                            == scope.site_id,
                        )
                    )
                ).all()
            )
        return tuple(self._target_context_capsule_handoff_result_from_row(row) for row in rows)

    async def bind_target_context_capsule_consumer(
        self, request: WorkflowTargetContextCapsuleConsumerBindingRequest
    ) -> WorkflowTargetContextCapsuleConsumerBindingResult:
        statuses = WorkflowTargetContextCapsuleConsumerBindingStatus
        try:
            validate_workflow_target_context_capsule_consumer_binding_request(request)
        except (TypeError, ValueError):
            return WorkflowTargetContextCapsuleConsumerBindingResult(
                statuses.EVIDENCE_CONFLICT, None
            )
        if not self._target_context_capsule_consumer_binding_policy_matches(request):
            return WorkflowTargetContextCapsuleConsumerBindingResult(
                statuses.EVIDENCE_CONFLICT, None
            )

        # Historical exact replay is deliberately resolved before any live-source
        # currentness query, so later expiry cannot hide an immutable prior result.
        async with self._sessions() as session:
            replay = await self._target_context_capsule_consumer_binding_replay(
                session, request=request, for_update=False
            )
            if replay is not None:
                return replay

        async with self._sessions() as session:
            locked = await self._lock_target_context_capsule_consumer_binding_sources(
                session, request=request
            )
            replay = self._target_context_capsule_consumer_binding_replay_from_locked(
                locked, request=request
            )
            if replay is not None:
                await session.rollback()
                return replay
            if locked.existing_bindings:
                await session.rollback()
                return WorkflowTargetContextCapsuleConsumerBindingResult(
                    statuses.ALREADY_BOUND, None
                )
            evidence = self._target_context_capsule_consumer_binding_evidence(
                locked, request=request
            )
            if evidence is None:
                await session.rollback()
                return WorkflowTargetContextCapsuleConsumerBindingResult(
                    statuses.EVIDENCE_CONFLICT, None
                )

            commit_observed_at = cast(
                datetime, await session.scalar(select(func.clock_timestamp()))
            )
            locked = dataclass_replace(locked, observed_at=commit_observed_at)
            evidence = self._target_context_capsule_consumer_binding_evidence(
                locked, request=request
            )
            if evidence is None:
                await session.rollback()
                return WorkflowTargetContextCapsuleConsumerBindingResult(
                    statuses.EVIDENCE_CONFLICT, None
                )
            binding, audit_payload = self._target_context_capsule_consumer_binding(
                request=request,
                evidence=evidence,
                bound_at=commit_observed_at,
            )
            try:
                session.add(self._target_context_capsule_consumer_binding_model(binding))
                await session.flush()
                session.add(
                    self._target_context_capsule_consumer_binding_claim_model(
                        request, binding=binding, audit_payload=audit_payload
                    )
                )
                await session.commit()
                return WorkflowTargetContextCapsuleConsumerBindingResult(statuses.BOUND, binding)
            except IntegrityError:
                await session.rollback()

        async with self._sessions() as session:
            replay = await self._target_context_capsule_consumer_binding_replay(
                session, request=request, for_update=False
            )
            if replay is not None:
                return replay
            opening_row = await session.get(
                WorkflowEventPhysicalTransportTargetContextArtifactOpeningResultModel,
                request.opening_result_id,
            )
            existing = None
            if opening_row is not None and opening_row.sealed_capsule_id is not None:
                existing = await session.scalar(
                    select(WorkflowProtectedTransportTargetContextCapsuleConsumerBindingModel)
                    .where(
                        or_(
                            WorkflowProtectedTransportTargetContextCapsuleConsumerBindingModel.opening_result_id
                            == request.opening_result_id,
                            WorkflowProtectedTransportTargetContextCapsuleConsumerBindingModel.sealed_capsule_id
                            == opening_row.sealed_capsule_id,
                        )
                    )
                    .limit(1)
                )
            return WorkflowTargetContextCapsuleConsumerBindingResult(
                statuses.ALREADY_BOUND if existing is not None else statuses.EVIDENCE_CONFLICT,
                None,
            )

    async def list_target_context_capsule_consumer_bindings(
        self, *, scope: WorkflowScope, limit: int
    ) -> tuple[WorkflowProtectedTransportTargetContextCapsuleConsumerBinding, ...]:
        if not 1 <= limit <= 256:
            raise ValueError("target context capsule consumer binding limit is invalid")
        async with self._sessions() as session:
            rows = tuple(
                (
                    await session.scalars(
                        select(WorkflowProtectedTransportTargetContextCapsuleConsumerBindingModel)
                        .where(
                            WorkflowProtectedTransportTargetContextCapsuleConsumerBindingModel.organization_id
                            == scope.organization_id,
                            WorkflowProtectedTransportTargetContextCapsuleConsumerBindingModel.environment_id
                            == scope.environment_id,
                            WorkflowProtectedTransportTargetContextCapsuleConsumerBindingModel.site_id
                            == scope.site_id,
                        )
                        .order_by(
                            WorkflowProtectedTransportTargetContextCapsuleConsumerBindingModel.bound_at.desc(),
                            WorkflowProtectedTransportTargetContextCapsuleConsumerBindingModel.binding_id,
                        )
                        .limit(limit)
                    )
                ).all()
            )
            claims = {
                row.binding_id: row
                for row in (
                    await session.scalars(
                        select(
                            WorkflowProtectedTransportTargetContextCapsuleConsumerBindingClaimModel
                        ).where(
                            WorkflowProtectedTransportTargetContextCapsuleConsumerBindingClaimModel.binding_id.in_(
                                tuple(item.binding_id for item in rows)
                            )
                        )
                    )
                ).all()
            }
        result: list[WorkflowProtectedTransportTargetContextCapsuleConsumerBinding] = []
        for row in rows:
            claim = claims.get(row.binding_id)
            if claim is None:
                self._target_context_capsule_consumer_binding_contract_violation()
            binding = self._target_context_capsule_consumer_binding_from_row(row)
            self._target_context_capsule_consumer_binding_from_claim(
                cast(Any, claim), binding_row=row
            )
            result.append(binding)
        return tuple(result)

    async def _lock_target_context_capsule_consumer_binding_sources(
        self,
        session: AsyncSession,
        *,
        request: WorkflowTargetContextCapsuleConsumerBindingRequest,
    ) -> _TargetContextCapsuleConsumerBindingLockedSources:
        # Opening evidence is append-only and may be read to discover the root
        # binding. Mutable lineage is then locked through the shared canonical
        # target-context order before event and artifact rows are locked.
        opening_hint = await session.get(
            WorkflowEventPhysicalTransportTargetContextArtifactOpeningResultModel,
            request.opening_result_id,
        )
        access = None
        if opening_hint is not None:
            access = await self._lock_target_context_access_sources(
                session,
                request=cast(
                    Any,
                    type(
                        "_TargetContextBindingReference",
                        (),
                        {
                            "expected_target_context_binding_id": (
                                opening_hint.target_context_binding_id
                            )
                        },
                    )(),
                ),
            )

        outbox = None if access is None else access.outbox
        event = artifact = None
        if outbox is not None:
            event = cast(
                WorkflowDispatchEventEnvelopeModel | None,
                await session.scalar(
                    select(WorkflowDispatchEventEnvelopeModel)
                    .where(
                        WorkflowDispatchEventEnvelopeModel.outbox_entry_id == outbox.outbox_entry_id
                    )
                    .with_for_update()
                ),
            )
            artifact = cast(
                WorkflowEventByteArtifactModel | None,
                await session.scalar(
                    select(WorkflowEventByteArtifactModel)
                    .where(WorkflowEventByteArtifactModel.outbox_entry_id == outbox.outbox_entry_id)
                    .with_for_update()
                ),
            )

        opening_lease = opening_claim = opening_attempt = opening_result = None
        if opening_hint is not None:
            opening_lease = cast(
                WorkflowEventPhysicalTransportTargetContextAccessAuthorizationLeaseModel | None,
                await session.scalar(
                    select(WorkflowEventPhysicalTransportTargetContextAccessAuthorizationLeaseModel)
                    .where(
                        WorkflowEventPhysicalTransportTargetContextAccessAuthorizationLeaseModel.authorization_lease_id
                        == opening_hint.authorization_lease_id
                    )
                    .with_for_update()
                ),
            )
            opening_claim = cast(
                WorkflowEventPhysicalTransportTargetContextAccessConsumptionClaimModel | None,
                await session.scalar(
                    select(WorkflowEventPhysicalTransportTargetContextAccessConsumptionClaimModel)
                    .where(
                        WorkflowEventPhysicalTransportTargetContextAccessConsumptionClaimModel.claim_id
                        == opening_hint.consumption_claim_id
                    )
                    .with_for_update()
                ),
            )
            opening_attempt = cast(
                WorkflowEventPhysicalTransportTargetContextArtifactOpeningAttemptModel | None,
                await session.scalar(
                    select(WorkflowEventPhysicalTransportTargetContextArtifactOpeningAttemptModel)
                    .where(
                        WorkflowEventPhysicalTransportTargetContextArtifactOpeningAttemptModel.attempt_id
                        == opening_hint.attempt_id
                    )
                    .with_for_update()
                ),
            )
            opening_result = cast(
                WorkflowEventPhysicalTransportTargetContextArtifactOpeningResultModel | None,
                await session.scalar(
                    select(WorkflowEventPhysicalTransportTargetContextArtifactOpeningResultModel)
                    .where(
                        WorkflowEventPhysicalTransportTargetContextArtifactOpeningResultModel.opening_id
                        == request.opening_result_id
                    )
                    .with_for_update()
                ),
            )

        scope_id = self._target_context_capsule_consumer_binding_idempotency_scope(
            request.scope,
            request.binder_subject_id,
            request.binder_audience,
        )
        idempotency_hint = cast(
            WorkflowProtectedTransportTargetContextCapsuleConsumerBindingClaimModel | None,
            await session.scalar(
                select(
                    WorkflowProtectedTransportTargetContextCapsuleConsumerBindingClaimModel
                ).where(
                    WorkflowProtectedTransportTargetContextCapsuleConsumerBindingClaimModel.idempotency_scope_id
                    == scope_id,
                    WorkflowProtectedTransportTargetContextCapsuleConsumerBindingClaimModel.idempotency_key
                    == request.idempotency_key,
                )
            ),
        )
        capsule_id = None if opening_hint is None else opening_hint.sealed_capsule_id
        existing_predicate = (
            WorkflowProtectedTransportTargetContextCapsuleConsumerBindingModel.opening_result_id
            == request.opening_result_id
        )
        if capsule_id is not None:
            existing_predicate = or_(
                existing_predicate,
                WorkflowProtectedTransportTargetContextCapsuleConsumerBindingModel.sealed_capsule_id
                == capsule_id,
            )
        if idempotency_hint is not None:
            existing_predicate = or_(
                existing_predicate,
                WorkflowProtectedTransportTargetContextCapsuleConsumerBindingModel.binding_id
                == idempotency_hint.binding_id,
            )
        existing_bindings = tuple(
            (
                await session.scalars(
                    select(WorkflowProtectedTransportTargetContextCapsuleConsumerBindingModel)
                    .where(existing_predicate)
                    .with_for_update()
                )
            ).all()
        )
        idempotency_claim = cast(
            WorkflowProtectedTransportTargetContextCapsuleConsumerBindingClaimModel | None,
            await session.scalar(
                select(WorkflowProtectedTransportTargetContextCapsuleConsumerBindingClaimModel)
                .where(
                    WorkflowProtectedTransportTargetContextCapsuleConsumerBindingClaimModel.idempotency_scope_id
                    == scope_id,
                    WorkflowProtectedTransportTargetContextCapsuleConsumerBindingClaimModel.idempotency_key
                    == request.idempotency_key,
                )
                .with_for_update()
            ),
        )
        observed_at = cast(datetime, await session.scalar(select(func.clock_timestamp())))
        return _TargetContextCapsuleConsumerBindingLockedSources(
            outbox=outbox,
            event=event,
            artifact=artifact,
            access=access,
            opening_lease=opening_lease,
            opening_claim=opening_claim,
            opening_attempt=opening_attempt,
            opening_result=opening_result,
            existing_bindings=existing_bindings,
            idempotency_claim=idempotency_claim,
            observed_at=observed_at,
        )

    @classmethod
    def _target_context_capsule_consumer_binding_evidence(
        cls,
        locked: _TargetContextCapsuleConsumerBindingLockedSources,
        *,
        request: WorkflowTargetContextCapsuleConsumerBindingRequest,
    ) -> dict[str, Any] | None:
        access = locked.access
        if access is None or any(
            value is None
            for value in (
                locked.outbox,
                locked.event,
                locked.artifact,
                locked.opening_lease,
                locked.opening_claim,
                locked.opening_attempt,
                locked.opening_result,
                access.binding,
                access.endpoint_result,
                access.credential_result,
                access.route_binding,
                access.logical_binding,
                access.outbox,
                access.route_snapshot,
                access.route_head,
                access.credential_binding,
                access.credential_snapshot,
                access.credential_head,
                access.materialization_chains,
            )
        ):
            return None
        try:
            opening_lease = cls._target_context_access_lease_from_row(
                cast(Any, locked.opening_lease)
            )
            opening_claim = cls._target_context_artifact_opening_claim_from_row(
                cast(Any, locked.opening_claim)
            )
            opening_attempt = cls._target_context_artifact_opening_attempt_from_row(
                cast(Any, locked.opening_attempt)
            )
            opening_result = cls._target_context_artifact_opening_result_from_row(
                cast(Any, locked.opening_result)
            )
            target_context = cls._target_context_binding_from_row(cast(Any, access.binding))
            endpoint = cls._endpoint_materialization_result_from_row(
                cast(Any, access.endpoint_result)
            )
            credential = cls._credential_materialization_result_from_row(
                cast(Any, access.credential_result)
            )
            route_binding = cls._physical_transport_route_binding_from_row(
                cast(Any, access.route_binding)
            )
            logical_binding = cls._event_logical_channel_binding_from_row(
                cast(Any, access.logical_binding)
            )
            outbox = cls._dispatch_outbox_from_row(cast(Any, locked.outbox))
            access_outbox = cls._dispatch_outbox_from_row(cast(Any, access.outbox))
            event = cls._dispatch_event_envelope_from_row(cast(Any, locked.event))
            artifact = cls._event_byte_artifact_from_row(cast(Any, locked.artifact))
            route_snapshot = cls._transport_route_snapshot_from_row(
                cast(Any, access.route_snapshot)
            )
            route_head = cls._route_selection_head_from_row(cast(Any, access.route_head))
            credential_binding = cls._credential_assignment_binding_from_row(
                cast(Any, access.credential_binding)
            )
            credential_snapshot = cls._credential_assignment_snapshot_from_row(
                cast(Any, access.credential_snapshot)
            )
            credential_head = cast(
                DeploymentPhysicalTransportCredentialAssignment, access.credential_head
            )
            opening_lease_row = cast(
                WorkflowEventPhysicalTransportTargetContextAccessAuthorizationLeaseModel,
                locked.opening_lease,
            )
            binding_policy = (
                code_owned_workflow_event_physical_transport_target_context_binding_policy()
            )
            chain_request = WorkflowEventPhysicalTransportTargetContextBindingRequest(
                expected_endpoint_materialization_id=endpoint.materialization_id,
                expected_endpoint_materialization_digest=endpoint.canonical_digest,
                expected_credential_materialization_id=credential.materialization_id,
                expected_credential_materialization_digest=credential.canonical_digest,
                expected_policy_id=binding_policy.policy_id,
                expected_policy_version=binding_policy.policy_version,
                expected_policy_digest=binding_policy.canonical_digest,
                scope=target_context.scope,
                binder_subject_id=target_context.binder_subject_id,
                requested_at=locked.observed_at,
                idempotency_key="capsule-consumer-chain-revalidation",
                request_fingerprint=canonical_digest(
                    {
                        "binding_digest": target_context.canonical_digest,
                        "binding_id": target_context.binding_id,
                        "operation": "capsule-consumer-chain-revalidation",
                    }
                ),
                required_precommit_audit=cast(Any, None),
            )
            chain_evidence = cls._target_context_binding_evidence(
                cast(_TargetContextLockedSources, access.materialization_chains),
                request=chain_request,
                observed_at=locked.observed_at,
                require_live_overlap=True,
            )
        except Exception:
            return None
        if chain_evidence is None or not cls._target_context_artifact_opening_lineage_matches(
            opening_claim, opening_attempt, opening_result
        ):
            return None
        if (
            opening_result.state
            is not (
                WorkflowEventPhysicalTransportTargetContextArtifactOpeningResultState
            ).OPENED_PROTECTED
            or opening_result.failure_class is not None
            or opening_result.sealed_capsule_id is None
            or opening_result.sealed_capsule_digest is None
            or opening_result.usable_until is None
            or opening_result.capsule_is_bearer_capability
            or not opening_result.protected_sources_closed
            or not opening_result.cleanup_confirmed
            or endpoint.usable_until is None
            or credential.usable_until is None
        ):
            return None
        policy = (
            code_owned_workflow_protected_transport_target_context_capsule_consumer_binding_policy()
        )
        deadline = min(
            opening_result.usable_until,
            opening_lease.valid_until,
            opening_lease.joint_usable_until,
            target_context.joint_usable_until,
            endpoint.usable_until,
            credential.usable_until,
            credential_head.expires_at,
        )
        event_scope = event.payload.scope
        scope_objects = (
            opening_lease.scope,
            opening_claim.scope,
            opening_attempt.scope,
            opening_result.scope,
            target_context.scope,
            endpoint.scope,
            credential.scope,
            route_binding.scope,
            logical_binding.scope,
            outbox.scope,
            artifact.scope,
            route_snapshot.scope,
            route_head.scope,
            credential_binding.scope,
            credential_snapshot.scope,
            credential_head.scope,
            event_scope,
        )
        lineage_matches = (
            opening_result.opening_id == request.opening_result_id
            and opening_result.canonical_digest == request.opening_result_digest
            and opening_result.target_context_binding_id == target_context.binding_id
            and opening_result.target_context_binding_digest == target_context.canonical_digest
            and opening_result.target_context_commitment == target_context.target_context_commitment
            and opening_result.authorization_lease_id == opening_lease.authorization_lease_id
            and opening_result.authorization_lease_digest == opening_lease.canonical_digest
            and opening_lease.target_context_binding_id == target_context.binding_id
            and opening_lease.target_context_binding_digest == target_context.canonical_digest
            and opening_lease.target_context_commitment == target_context.target_context_commitment
            and opening_lease_row.outbox_entry_id == outbox.outbox_entry_id
            and opening_lease_row.outbox_entry_digest == outbox.canonical_digest
            and target_context.physical_transport_route_binding_id == route_binding.binding_id
            and target_context.physical_transport_route_binding_digest
            == route_binding.canonical_digest
            and route_binding.logical_channel_binding_id == logical_binding.binding_id
            and route_binding.logical_channel_binding_digest == logical_binding.canonical_digest
            and logical_binding.outbox_entry_id == outbox.outbox_entry_id
            and logical_binding.outbox_entry_digest == outbox.canonical_digest
            and logical_binding.event_id == event.event_id == artifact.event_id
            and logical_binding.event_digest == event.canonical_digest == artifact.event_digest
            and logical_binding.artifact_id == artifact.artifact_id
            and logical_binding.artifact_digest == artifact.canonical_digest
            and event.payload.outbox_entry_id == outbox.outbox_entry_id
            and event.payload.outbox_entry_digest == outbox.canonical_digest
            and artifact.outbox_entry_id == outbox.outbox_entry_id
            and artifact.outbox_entry_digest == outbox.canonical_digest
            and outbox == access_outbox
            and target_context.transport_route_snapshot_id == route_snapshot.snapshot_id
            and target_context.transport_route_snapshot_digest == route_snapshot.canonical_digest
            and target_context.physical_transport_credential_assignment_binding_id
            == credential_binding.binding_id
            and target_context.physical_transport_credential_assignment_binding_digest
            == credential_binding.canonical_digest
            and target_context.credential_assignment_snapshot_id == credential_snapshot.snapshot_id
            and target_context.credential_assignment_snapshot_digest
            == credential_snapshot.canonical_digest
            and chain_evidence["route_binding"] == route_binding
            and chain_evidence["route_snapshot"] == route_snapshot
            and chain_evidence["endpoint_result"] == endpoint
            and chain_evidence["credential_binding"] == credential_binding
            and chain_evidence["credential_snapshot"] == credential_snapshot
            and chain_evidence["credential_result"] == credential
        )
        workflow_lineage_matches = all(
            (
                item.plan_id == outbox.plan_id
                and item.plan_digest == outbox.plan_digest
                and item.run_id == outbox.run_id
                and item.run_digest == outbox.run_digest
                and item.step_run_id == outbox.step_run_id
                and item.step_run_digest == outbox.step_run_digest
                and item.attempt_id == outbox.attempt_id
                and item.attempt_digest == outbox.attempt_digest
                and item.target_id == outbox.target_id
                and item.target_type == outbox.target_type
            )
            for item in (event.payload, artifact, logical_binding)
        )
        current_route_matches = (
            route_head.current
            and route_head.selection_active
            and route_head.selection_eligible
            and not route_head.selection_suspended
            and not route_head.selection_withdrawn
            and not route_head.selection_superseded
            and route_head.route_set_id == route_snapshot.route_set_id
            and route_head.route_set_revision == route_snapshot.route_set_revision
            and route_head.selection_epoch_id == route_snapshot.selection_epoch_id
            and route_head.selection_epoch_revision == route_snapshot.selection_epoch_revision
            and route_head.selected_route_id == route_snapshot.route_id
            and route_head.selected_route_revision == route_snapshot.route_revision
            and route_head.selected_route_digest == route_snapshot.source_route_digest
            and opening_lease_row.route_head_id == route_head.head_id
            and opening_lease_row.route_head_digest == route_head.canonical_digest
            and opening_lease_row.route_head_generation == route_head.generation
            and opening_lease_row.route_head_fencing_token_digest == route_head.fencing_token_digest
        )
        current_credential_matches = (
            credential_binding.credential_assignment_snapshot_id == credential_snapshot.snapshot_id
            and credential_head.assignment_id == credential_snapshot.assignment_id
            and credential_head.assignment_revision == credential_snapshot.assignment_revision
            and credential_head.canonical_digest == credential_snapshot.source_assignment_digest
            and credential_head.credential_generation == credential_snapshot.credential_generation
            and credential_head.rotation_epoch == credential_snapshot.rotation_epoch
            and credential_head.active
            and not credential_head.revoked
            and credential_head.activated_at <= locked.observed_at
            and opening_lease_row.assignment_id == credential_head.assignment_id
            and opening_lease_row.assignment_revision == credential_head.assignment_revision
            and opening_lease_row.assignment_digest == credential_head.canonical_digest
            and opening_lease_row.credential_generation == credential_head.credential_generation
            and opening_lease_row.rotation_epoch == credential_head.rotation_epoch
            and opening_lease_row.assignment_expires_at == credential_head.expires_at
        )
        if not (
            all(scope == request.scope for scope in scope_objects)
            and lineage_matches
            and workflow_lineage_matches
            and current_route_matches
            and current_credential_matches
            and outbox.state is WorkflowDispatchOutboxState.PENDING_PUBLICATION
            and event.state is WorkflowDispatchEventEnvelopeState.PREPARED
            and artifact.state is WorkflowEventByteArtifactState.MATERIALIZED
            and logical_binding.state is WorkflowEventLogicalChannelBindingState.BOUND
            and opening_lease.authority.protected_artifact_access_authorized
            and all(
                value is False
                for name, value in opening_lease.authority.canonical_value().items()
                if name != "protected_artifact_access_authorized"
            )
            and not endpoint.protected_artifact_revoked
            and not credential.protected_artifact_revoked
            and request.expected_policy_id == policy.policy_id
            and request.expected_policy_version == policy.policy_version
            and request.expected_policy_digest == policy.canonical_digest
            and request.expected_consumer_subject_id == policy.consumer_subject_id
            and request.expected_consumer_audience == policy.consumer_audience
            and request.expected_consumer_contract_id == policy.consumer_contract_id
            and request.expected_consumer_contract_version == policy.consumer_contract_version
            and request.expected_purpose_id == policy.purpose_id
            and locked.observed_at + timedelta(seconds=request.minimum_remaining_lifetime_seconds)
            <= deadline
        ):
            return None
        return {
            "artifact": artifact,
            "credential_binding": credential_binding,
            "credential_snapshot": credential_snapshot,
            "deadline": deadline,
            "event": event,
            "logical_binding": logical_binding,
            "opening_attempt": opening_attempt,
            "opening_claim": opening_claim,
            "opening_result": opening_result,
            "outbox": outbox,
            "route_binding": route_binding,
            "route_snapshot": route_snapshot,
            "target_context": target_context,
        }

    async def _target_context_capsule_consumer_binding_replay(
        self,
        session: AsyncSession,
        *,
        request: WorkflowTargetContextCapsuleConsumerBindingRequest,
        for_update: bool,
    ) -> WorkflowTargetContextCapsuleConsumerBindingResult | None:
        statement = select(
            WorkflowProtectedTransportTargetContextCapsuleConsumerBindingClaimModel
        ).where(
            WorkflowProtectedTransportTargetContextCapsuleConsumerBindingClaimModel.idempotency_scope_id
            == self._target_context_capsule_consumer_binding_idempotency_scope(
                request.scope, request.binder_subject_id, request.binder_audience
            ),
            WorkflowProtectedTransportTargetContextCapsuleConsumerBindingClaimModel.idempotency_key
            == request.idempotency_key,
        )
        if for_update:
            statement = statement.with_for_update()
        claim = cast(
            WorkflowProtectedTransportTargetContextCapsuleConsumerBindingClaimModel | None,
            await session.scalar(statement),
        )
        statuses = WorkflowTargetContextCapsuleConsumerBindingStatus
        if claim is not None:
            binding_statement = select(
                WorkflowProtectedTransportTargetContextCapsuleConsumerBindingModel
            ).where(
                WorkflowProtectedTransportTargetContextCapsuleConsumerBindingModel.binding_id
                == claim.binding_id
            )
            if for_update:
                binding_statement = binding_statement.with_for_update()
            binding_row = cast(
                WorkflowProtectedTransportTargetContextCapsuleConsumerBindingModel | None,
                await session.scalar(binding_statement),
            )
            if binding_row is None:
                self._target_context_capsule_consumer_binding_contract_violation()
            binding = self._target_context_capsule_consumer_binding_from_claim(
                claim, binding_row=binding_row
            )
            exact = self._target_context_capsule_consumer_binding_request_matches(
                request, binding=binding, claim=claim
            )
            return WorkflowTargetContextCapsuleConsumerBindingResult(
                statuses.REPLAY if exact else statuses.IDEMPOTENCY_CONFLICT,
                binding if exact else None,
            )
        existing_statement = select(
            WorkflowProtectedTransportTargetContextCapsuleConsumerBindingModel
        ).where(
            WorkflowProtectedTransportTargetContextCapsuleConsumerBindingModel.opening_result_id
            == request.opening_result_id
        )
        if for_update:
            existing_statement = existing_statement.with_for_update()
        existing = await session.scalar(existing_statement)
        if existing is not None:
            return WorkflowTargetContextCapsuleConsumerBindingResult(statuses.ALREADY_BOUND, None)
        return None

    def _target_context_capsule_consumer_binding_replay_from_locked(
        self,
        locked: _TargetContextCapsuleConsumerBindingLockedSources,
        *,
        request: WorkflowTargetContextCapsuleConsumerBindingRequest,
    ) -> WorkflowTargetContextCapsuleConsumerBindingResult | None:
        claim = locked.idempotency_claim
        statuses = WorkflowTargetContextCapsuleConsumerBindingStatus
        if claim is None:
            return None
        binding_row = next(
            (row for row in locked.existing_bindings if row.binding_id == claim.binding_id),
            None,
        )
        if binding_row is None:
            self._target_context_capsule_consumer_binding_contract_violation()
        binding = self._target_context_capsule_consumer_binding_from_claim(
            claim, binding_row=binding_row
        )
        exact = self._target_context_capsule_consumer_binding_request_matches(
            request, binding=binding, claim=claim
        )
        return WorkflowTargetContextCapsuleConsumerBindingResult(
            statuses.REPLAY if exact else statuses.IDEMPOTENCY_CONFLICT,
            binding if exact else None,
        )

    @staticmethod
    def _target_context_capsule_consumer_binding_request_matches(
        request: WorkflowTargetContextCapsuleConsumerBindingRequest,
        *,
        binding: WorkflowProtectedTransportTargetContextCapsuleConsumerBinding,
        claim: WorkflowProtectedTransportTargetContextCapsuleConsumerBindingClaimModel,
    ) -> bool:
        return bool(
            binding.opening_result_id == request.opening_result_id
            and binding.opening_result_digest == request.opening_result_digest
            and binding.policy_id == request.expected_policy_id
            and binding.policy_version == request.expected_policy_version
            and binding.policy_digest == request.expected_policy_digest
            and binding.consumer_subject_id == request.expected_consumer_subject_id
            and binding.consumer_audience == request.expected_consumer_audience
            and binding.consumer_contract_id == request.expected_consumer_contract_id
            and binding.consumer_contract_version == request.expected_consumer_contract_version
            and binding.purpose_id == request.expected_purpose_id
            and binding.scope == request.scope
            and binding.binder_subject_id == request.binder_subject_id
            and binding.binder_audience == request.binder_audience
            and binding.request_fingerprint == request.request_fingerprint
            and binding.idempotency_digest == request.idempotency_digest
            and claim.idempotency_key == request.idempotency_key
            and claim.idempotency_digest == request.idempotency_digest
            and claim.request_fingerprint == request.request_fingerprint
        )

