    @staticmethod
    def _target_context_capsule_consumer_binding_policy_matches(
        request: WorkflowTargetContextCapsuleConsumerBindingRequest,
    ) -> bool:
        policy = (
            code_owned_workflow_protected_transport_target_context_capsule_consumer_binding_policy()
        )
        return bool(
            request.expected_policy_id == policy.policy_id
            and request.expected_policy_version == policy.policy_version
            and request.expected_policy_digest == policy.canonical_digest
            and request.expected_consumer_subject_id == policy.consumer_subject_id
            and request.expected_consumer_audience == policy.consumer_audience
            and request.expected_consumer_contract_id == policy.consumer_contract_id
            and request.expected_consumer_contract_version == policy.consumer_contract_version
            and request.expected_purpose_id == policy.purpose_id
            and request.minimum_remaining_lifetime_seconds
            == policy.minimum_remaining_lifetime_seconds
        )

    @staticmethod
    def _target_context_capsule_consumer_binding_contract_violation() -> NoReturn:
        raise WorkflowProtectedTransportTargetContextCapsuleConsumerBindingError(
            "workflow_target_context_capsule_consumer_binding_repository_contract_violation",
            "Stored target-context capsule consumer binding evidence is invalid.",
        )

    async def _lock_target_context_capsule_handoff_authorization_sources(
        self,
        session: AsyncSession,
        *,
        request: WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseRequest,
    ) -> _TargetContextCapsuleHandoffAuthorizationLockedSources:
        # Binding and claim are append-only hints used only to discover the
        # canonical IMP-211 lock roots. They are locked again by the shared
        # target-context lock chain before handoff rows are considered.
        binding_hint = await session.get(
            WorkflowProtectedTransportTargetContextCapsuleConsumerBindingModel,
            request.expected_consumer_binding_id,
        )
        binding_claim_hint = None
        binding_request = None
        if binding_hint is not None:
            binding_claim_hint = cast(
                WorkflowProtectedTransportTargetContextCapsuleConsumerBindingClaimModel | None,
                await session.scalar(
                    select(
                        WorkflowProtectedTransportTargetContextCapsuleConsumerBindingClaimModel
                    ).where(
                        WorkflowProtectedTransportTargetContextCapsuleConsumerBindingClaimModel.binding_id
                        == binding_hint.binding_id
                    )
                ),
            )
        if binding_hint is not None and binding_claim_hint is not None:
            binding_request = self._target_context_capsule_handoff_binding_request(
                binding_hint,
                binding_claim_hint,
                requested_at=request.requested_at,
            )
        consumer_binding_sources = (
            None
            if binding_request is None
            else await self._lock_target_context_capsule_consumer_binding_sources(
                session,
                request=binding_request,
            )
        )
        consumer_binding = None
        consumer_binding_claim = None
        if consumer_binding_sources is not None:
            consumer_binding = next(
                (
                    row
                    for row in consumer_binding_sources.existing_bindings
                    if row.binding_id == request.expected_consumer_binding_id
                ),
                None,
            )
            consumer_binding_claim = consumer_binding_sources.idempotency_claim

        capsule_id = None if consumer_binding is None else consumer_binding.sealed_capsule_id
        existing_leases: tuple[
            WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseModel, ...
        ] = ()
        if capsule_id is not None:
            existing_leases = tuple(
                (
                    await session.scalars(
                        select(
                            WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseModel
                        )
                        .where(
                            or_(
                                WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseModel.consumer_binding_id
                                == request.expected_consumer_binding_id,
                                WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseModel.sealed_capsule_id
                                == capsule_id,
                            )
                        )
                        .with_for_update()
                    )
                ).all()
            )
        scope_id = self._target_context_capsule_handoff_idempotency_scope(
            request.scope,
            request.consumer_subject_id,
            request.consumer_audience,
        )
        idempotency_claim = cast(
            WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationClaimModel | None,
            await session.scalar(
                select(WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationClaimModel)
                .where(
                    WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationClaimModel.idempotency_scope_id
                    == scope_id,
                    WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationClaimModel.idempotency_key
                    == request.idempotency_key,
                )
                .with_for_update()
            ),
        )
        observed_at = cast(datetime, await session.scalar(select(func.clock_timestamp())))
        return _TargetContextCapsuleHandoffAuthorizationLockedSources(
            consumer_binding_sources=consumer_binding_sources,
            consumer_binding=consumer_binding,
            consumer_binding_claim=consumer_binding_claim,
            existing_leases=existing_leases,
            idempotency_claim=idempotency_claim,
            observed_at=observed_at,
        )

    @staticmethod
    def _target_context_capsule_handoff_retimed_request(
        request: WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseRequest,
        *,
        issued_at: datetime,
    ) -> WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseRequest:
        valid_until = issued_at + timedelta(seconds=1)
        digest_payload = request.candidate.digest_payload()
        digest_payload["issued_at"] = issued_at.isoformat()
        digest_payload["valid_until"] = valid_until.isoformat()
        candidate = dataclass_replace(
            request.candidate,
            issued_at=issued_at,
            valid_until=valid_until,
            canonical_digest=canonical_digest(digest_payload),
        )
        return dataclass_replace(
            request,
            requested_at=issued_at,
            candidate=candidate,
        )

    @classmethod
    def _target_context_capsule_handoff_binding_request(
        cls,
        binding_row: WorkflowProtectedTransportTargetContextCapsuleConsumerBindingModel,
        binding_claim: WorkflowProtectedTransportTargetContextCapsuleConsumerBindingClaimModel,
        *,
        requested_at: datetime,
    ) -> WorkflowTargetContextCapsuleConsumerBindingRequest:
        binding = cls._target_context_capsule_consumer_binding_from_row(binding_row)
        return WorkflowTargetContextCapsuleConsumerBindingRequest(
            opening_result_id=binding.opening_result_id,
            opening_result_digest=binding.opening_result_digest,
            expected_policy_id=binding.policy_id,
            expected_policy_version=binding.policy_version,
            expected_policy_digest=binding.policy_digest,
            expected_consumer_subject_id=binding.consumer_subject_id,
            expected_consumer_audience=binding.consumer_audience,
            expected_consumer_contract_id=binding.consumer_contract_id,
            expected_consumer_contract_version=binding.consumer_contract_version,
            expected_purpose_id=binding.purpose_id,
            minimum_remaining_lifetime_seconds=1,
            scope=binding.scope,
            binder_subject_id=binding.binder_subject_id,
            binder_audience=binding.binder_audience,
            requested_at=requested_at,
            idempotency_key=binding_claim.idempotency_key,
            idempotency_digest=binding.idempotency_digest,
            request_fingerprint=binding.request_fingerprint,
        )

    @classmethod
    def _target_context_capsule_handoff_evidence_matches(
        cls,
        *,
        request: WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseRequest,
        locked: _TargetContextCapsuleHandoffAuthorizationLockedSources,
        candidate: WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLease
        | None = None,
        require_candidate_attestation: bool = True,
    ) -> bool:
        sources = locked.consumer_binding_sources
        binding_row = locked.consumer_binding
        binding_claim = locked.consumer_binding_claim
        if sources is None or binding_row is None or binding_claim is None:
            return False
        try:
            binding = cls._target_context_capsule_consumer_binding_from_claim(
                binding_claim,
                binding_row=binding_row,
            )
            binding_request = cls._target_context_capsule_handoff_binding_request(
                binding_row,
                binding_claim,
                requested_at=locked.observed_at,
            )
            current_sources = dataclass_replace(sources, observed_at=locked.observed_at)
            evidence = cls._target_context_capsule_consumer_binding_evidence(
                current_sources,
                request=binding_request,
            )
            attestation = request.lifecycle_attestation
            lease = request.candidate if candidate is None else candidate
            attestation_digest = str(
                cls._capsule_lifecycle_attestation_value(attestation, "canonical_digest")
            )
            attestation_valid_until = cast(
                datetime,
                cls._capsule_lifecycle_attestation_value(attestation, "valid_until"),
            )
            attestation_observed_at = cast(
                datetime,
                cls._capsule_lifecycle_attestation_value(attestation, "observed_at"),
            )
            attestation_binding_id = str(
                cls._capsule_lifecycle_attestation_value(
                    attestation, "consumer_binding_id", "target_context_capsule_consumer_binding_id"
                )
            )
            attestation_binding_digest = str(
                cls._capsule_lifecycle_attestation_value(
                    attestation,
                    "consumer_binding_digest",
                    "target_context_capsule_consumer_binding_digest",
                )
            )
            attestation_capsule_id = str(
                cls._capsule_lifecycle_attestation_value(attestation, "sealed_capsule_id")
            )
            attestation_capsule_digest = str(
                cls._capsule_lifecycle_attestation_value(attestation, "sealed_capsule_digest")
            )
            signature_valid = cls._verify_capsule_lifecycle_attestation(request)
        except Exception:
            return False
        if evidence is None:
            return False
        policy = _handoff_authorization_policy()
        deadline = min(
            cast(datetime, evidence["deadline"]),
            binding.effective_until,
            attestation_valid_until,
        )
        authority = lease.authority.canonical_value()
        candidate_attestation_matches = not require_candidate_attestation or (
            lease.lifecycle_attestation_id
            == cls._capsule_lifecycle_attestation_value(attestation, "attestation_id")
            and lease.lifecycle_attestation_digest == attestation_digest
            and lease.lifecycle_attestation_valid_until == attestation_valid_until
        )
        return bool(
            signature_valid
            and binding.binding_id == request.expected_consumer_binding_id
            and binding.canonical_digest == request.expected_consumer_binding_digest
            and binding.scope == request.scope == lease.scope
            and binding.opening_result_id
            == request.expected_opening_result_id
            == lease.opening_result_id
            == attestation.opening_result_id
            and binding.opening_result_digest
            == request.expected_opening_result_digest
            == lease.opening_result_digest
            == attestation.opening_result_digest
            and binding.consumer_subject_id
            == request.consumer_subject_id
            == lease.consumer_subject_id
            and binding.consumer_audience == request.consumer_audience == lease.consumer_audience
            and binding.consumer_contract_id
            == request.consumer_contract_id
            == lease.consumer_contract_id
            and binding.consumer_contract_version
            == request.consumer_contract_version
            == lease.consumer_contract_version
            and binding.purpose_id == request.purpose_id == lease.purpose_id
            and binding.sealed_capsule_id
            == request.expected_sealed_capsule_id
            == lease.sealed_capsule_id
            == attestation_capsule_id
            and binding.sealed_capsule_digest
            == request.expected_sealed_capsule_digest
            == lease.sealed_capsule_digest
            == attestation_capsule_digest
            and binding.capsule_schema_id
            == request.expected_capsule_schema_id
            == lease.capsule_schema_id
            == attestation.capsule_schema_id
            and binding.capsule_schema_version
            == request.expected_capsule_schema_version
            == lease.capsule_schema_version
            == attestation.capsule_schema_version
            and not binding.capsule_is_bearer_capability
            and not getattr(lease, "lease_is_bearer_capability", False)
            and attestation_binding_id == binding.binding_id
            and attestation_binding_digest == binding.canonical_digest
            and policy.policy_id == lease.policy_id
            and policy.policy_version == lease.policy_version
            and request.expected_policy_digest == policy.canonical_digest == lease.policy_digest
            and request.expected_validity_window_seconds == policy.validity_window_seconds == 1
            and lease.valid_until - lease.issued_at == timedelta(seconds=1)
            and lease.issued_at <= locked.observed_at < lease.valid_until
            and attestation_observed_at <= locked.observed_at < attestation_valid_until
            and lease.valid_until <= deadline
            and lease.valid_until <= lease.effective_until
            and lease.single_use
            and not lease.renewable
            and not lease.transferable
            and candidate_attestation_matches
            and authority.get("target_context_capsule_handoff_authorized") is True
            and all(
                value is False
                for name, value in authority.items()
                if name != "target_context_capsule_handoff_authorized"
            )
        )

    @staticmethod
    def _capsule_lifecycle_attestation_value(
        attestation: WorkflowProtectedTargetContextCapsuleLifecycleAttestation,
        *names: str,
    ) -> object:
        for name in names:
            if hasattr(attestation, name):
                return getattr(attestation, name)
        raise ValueError("capsule lifecycle attestation contract is incomplete")

    @classmethod
    def _verify_capsule_lifecycle_attestation(
        cls,
        request: WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseRequest,
    ) -> bool:
        attestation = request.lifecycle_attestation
        if canonical_digest(attestation.digest_payload()) != attestation.canonical_digest:
            return False
        if (
            cls._capsule_lifecycle_attestation_value(attestation, "request_nonce_digest")
            != request.expected_request_nonce_digest
            or cls._capsule_lifecycle_attestation_value(
                attestation, "protected_store_attestor_id", "capsule_lifecycle_attestor_id"
            )
            != request.expected_lifecycle_attestor_id
            or cls._capsule_lifecycle_attestation_value(
                attestation,
                "protected_store_attestor_version",
                "capsule_lifecycle_attestor_version",
            )
            != request.expected_lifecycle_attestor_version
            or cls._capsule_lifecycle_attestation_value(attestation, "usable") is not True
            or cls._capsule_lifecycle_attestation_value(attestation, "revoked") is not False
            or cls._capsule_lifecycle_attestation_value(attestation, "destroyed") is not False
            or cls._capsule_lifecycle_attestation_value(attestation, "sealed") is not True
            or cls._capsule_lifecycle_attestation_value(attestation, "capsule_is_bearer_capability")
            is not False
        ):
            return False
        verifier = request.offline_signature_verifier
        result = verifier.verify_capsule_lifecycle_attestation(attestation)
        return result is True

    @classmethod
    def _target_context_capsule_handoff_request_is_valid(
        cls,
        request: WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseRequest,
    ) -> bool:
        candidate = request.candidate
        policy = _handoff_authorization_policy()
        try:
            validate_workflow_protected_transport_target_context_capsule_handoff_authorization_request(
                request
            )
            signature_valid = cls._verify_capsule_lifecycle_attestation(request)
        except Exception:
            return False
        return bool(
            signature_valid
            and request.expected_policy_digest == policy.canonical_digest
            and request.expected_validity_window_seconds == policy.validity_window_seconds == 1
            and request.expected_consumer_binding_id == candidate.consumer_binding_id
            and request.expected_consumer_binding_digest == candidate.consumer_binding_digest
            and request.consumer_subject_id == policy.consumer_subject_id
            and request.consumer_audience == policy.consumer_audience
            and candidate.consumer_subject_id == policy.consumer_subject_id
            and candidate.consumer_audience == policy.consumer_audience
            and candidate.consumer_contract_id == policy.consumer_contract_id
            and candidate.consumer_contract_version == policy.consumer_contract_version
            and candidate.purpose_id == policy.purpose_id
            and candidate.scope == request.scope
            and candidate.policy_id == policy.policy_id
            and candidate.policy_version == policy.policy_version
            and candidate.policy_digest == policy.canonical_digest
            and candidate.valid_until - candidate.issued_at == timedelta(seconds=1)
            and candidate.single_use
            and not candidate.renewable
            and not candidate.transferable
            and not getattr(candidate, "lease_is_bearer_capability", False)
            and 8 <= len(request.idempotency_key) <= 128
            and len(request.request_fingerprint) == 64
            and all(character in "0123456789abcdef" for character in request.request_fingerprint)
            and request.requested_at.tzinfo is not None
            and len(request.expected_request_nonce_digest) == 64
            and all(
                character in "0123456789abcdef"
                for character in request.expected_request_nonce_digest
            )
        )

    async def _target_context_capsule_handoff_replay(
        self,
        session: AsyncSession,
        *,
        request: WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseRequest,
        locked: _TargetContextCapsuleHandoffAuthorizationLockedSources,
    ) -> WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseResult | None:
        claim = locked.idempotency_claim
        if claim is None:
            return None
        lease_row = next(
            (
                row
                for row in locked.existing_leases
                if row.authorization_lease_id == claim.authorization_lease_id
            ),
            None,
        )
        if lease_row is None:
            lease_row = await session.get(
                WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseModel,
                claim.authorization_lease_id,
            )
        lease = self._target_context_capsule_handoff_lease_from_claim(claim, lease_row)
        statuses = WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseStatus
        if claim.request_fingerprint != request.request_fingerprint:
            return WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseResult(
                statuses.IDEMPOTENCY_CONFLICT, None
            )
        if (
            lease.valid_until <= locked.observed_at
            or lease.consumer_binding_id != request.expected_consumer_binding_id
            or lease.consumer_binding_digest != request.expected_consumer_binding_digest
            or lease.policy_digest != request.expected_policy_digest
            or lease.consumer_subject_id != request.consumer_subject_id
            or lease.consumer_audience != request.consumer_audience
            or not self._target_context_capsule_handoff_evidence_matches(
                request=request,
                locked=locked,
                candidate=lease,
                require_candidate_attestation=False,
            )
            or lease_row is None
            or lease_row.authorization_evidence_digest
            != canonical_digest(self._target_context_capsule_handoff_evidence_payload(locked))
        ):
            return WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseResult(
                statuses.EVIDENCE_CONFLICT, None
            )
        return WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseResult(
            statuses.REPLAY, lease, locked.observed_at
        )

    @classmethod
    def _target_context_capsule_handoff_evidence_payload(
        cls,
        locked: _TargetContextCapsuleHandoffAuthorizationLockedSources,
    ) -> dict[str, object]:
        sources = locked.consumer_binding_sources
        binding_row = locked.consumer_binding
        binding_claim = locked.consumer_binding_claim
        if (
            sources is None
            or sources.access is None
            or sources.access.route_head is None
            or sources.access.credential_head is None
            or binding_row is None
            or binding_claim is None
        ):
            cls._target_context_capsule_handoff_contract_violation()
        binding = cls._target_context_capsule_consumer_binding_from_claim(
            binding_claim,
            binding_row=binding_row,
        )
        route_head = cls._route_selection_head_from_row(cast(Any, sources.access.route_head))
        assignment = sources.access.credential_head
        return {
            "consumer_binding": {
                "authorization_audit_digest": binding.authorization_audit_digest,
                "binding_id": binding.binding_id,
                "canonical_digest": binding.canonical_digest,
                "effective_until": binding.effective_until.isoformat(),
            },
            "credential_assignment": {
                "assignment_id": assignment.assignment_id,
                "assignment_revision": assignment.assignment_revision,
                "canonical_digest": assignment.canonical_digest,
                "credential_generation": assignment.credential_generation,
                "expires_at": assignment.expires_at.isoformat(),
                "rotation_epoch": assignment.rotation_epoch,
            },
            "route_selection_head": {
                "canonical_digest": route_head.canonical_digest,
                "fencing_token_digest": route_head.fencing_token_digest,
                "generation": route_head.generation,
                "head_id": route_head.head_id,
            },
        }

    @staticmethod
    def _target_context_capsule_handoff_authority_columns(
        authority: WorkflowProtectedTransportTargetContextCapsuleHandoffLeaseAuthority,
    ) -> dict[str, bool]:
        return {
            name.replace("_authorized", "_authority_granted"): value
            for name, value in authority.canonical_value().items()
        }

    @classmethod
    def _target_context_capsule_handoff_lease_model(
        cls,
        request: WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseRequest,
        *,
        evidence_payload: dict[str, object],
    ) -> WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseModel:
        lease = request.candidate
        attestation = request.lifecycle_attestation
        audit_payload = cls._target_context_capsule_handoff_authorization_audit_payload(lease)
        return WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseModel(
            authorization_lease_id=lease.authorization_lease_id,
            consumer_binding_id=lease.consumer_binding_id,
            consumer_binding_digest=lease.consumer_binding_digest,
            opening_result_id=lease.opening_result_id,
            opening_result_digest=lease.opening_result_digest,
            sealed_capsule_id=lease.sealed_capsule_id,
            sealed_capsule_digest=lease.sealed_capsule_digest,
            capsule_schema_id=lease.capsule_schema_id,
            capsule_schema_version=lease.capsule_schema_version,
            capsule_is_bearer_capability=attestation.capsule_is_bearer_capability,
            lifecycle_attestation_id=lease.lifecycle_attestation_id,
            lifecycle_attestation_digest=lease.lifecycle_attestation_digest,
            lifecycle_attestation_valid_until=lease.lifecycle_attestation_valid_until,
            lifecycle_attestor_id=str(
                cls._capsule_lifecycle_attestation_value(
                    attestation, "protected_store_attestor_id", "capsule_lifecycle_attestor_id"
                )
            ),
            lifecycle_attestor_version=str(
                cls._capsule_lifecycle_attestation_value(
                    attestation,
                    "protected_store_attestor_version",
                    "capsule_lifecycle_attestor_version",
                )
            ),
            lifecycle_signing_key_id=str(
                cls._capsule_lifecycle_attestation_value(attestation, "signing_key_id")
            ),
            lifecycle_signature_algorithm=str(
                cls._capsule_lifecycle_attestation_value(attestation, "signature_algorithm")
            ),
            lifecycle_integrity_signature=str(
                cls._capsule_lifecycle_attestation_value(attestation, "integrity_signature")
            ),
            consumer_subject_id=lease.consumer_subject_id,
            consumer_audience=lease.consumer_audience,
            consumer_contract_id=lease.consumer_contract_id,
            consumer_contract_version=lease.consumer_contract_version,
            purpose_id=lease.purpose_id,
            policy_id=lease.policy_id,
            policy_version=lease.policy_version,
            policy_digest=lease.policy_digest,
            organization_id=lease.scope.organization_id,
            environment_id=lease.scope.environment_id,
            site_id=lease.scope.site_id,
            issued_at=lease.issued_at,
            valid_until=lease.valid_until,
            effective_until=lease.effective_until,
            single_use=lease.single_use,
            renewable=lease.renewable,
            transferable=lease.transferable,
            lease_is_bearer_capability=getattr(lease, "lease_is_bearer_capability", False),
            state=lease.state.value,
            **cls._target_context_capsule_handoff_authority_columns(lease.authority),
            authorization_evidence_digest=canonical_digest(evidence_payload),
            authorization_audit_digest=canonical_digest(audit_payload),
            canonical_digest=lease.canonical_digest,
            payload=lease.canonical_value(),
            lifecycle_attestation_payload=attestation.canonical_value(),
            authorization_evidence_payload=evidence_payload,
            authorization_audit_payload=audit_payload,
        )

    @classmethod
    def _target_context_capsule_handoff_lease_from_row(
        cls,
        row: WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseModel,
    ) -> WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLease:
        try:
            values = dict(row.payload)
            values["scope"] = WorkflowScope(**cast(Any, values["scope"]))
            for name in (
                "lifecycle_attestation_valid_until",
                "issued_at",
                "valid_until",
                "effective_until",
            ):
                values[name] = datetime.fromisoformat(str(values[name]))
            values["state"] = (
                WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseState(
                    str(values["state"])
                )
            )
            values["authority"] = (
                WorkflowProtectedTransportTargetContextCapsuleHandoffLeaseAuthority(
                    **cast(Any, values["authority"])
                )
            )
            lease = WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLease(
                **cast(Any, values)
            )
            attestation = cls._target_context_capsule_handoff_attestation_from_payload(
                row.lifecycle_attestation_payload
            )
            evidence_payload = dict(row.authorization_evidence_payload)
            audit_payload = cls._target_context_capsule_handoff_authorization_audit_payload(lease)
        except (KeyError, TypeError, ValueError) as exc:
            raise WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseError(
                "workflow_target_context_capsule_handoff_repository_contract_violation",
                "Stored target-context capsule handoff authorization evidence is invalid.",
            ) from exc
        authority_columns = cls._target_context_capsule_handoff_authority_columns(lease.authority)
        scalar_fields = (
            "authorization_lease_id",
            "consumer_binding_id",
            "consumer_binding_digest",
            "opening_result_id",
            "opening_result_digest",
            "sealed_capsule_id",
            "sealed_capsule_digest",
            "capsule_schema_id",
            "capsule_schema_version",
            "lifecycle_attestation_id",
            "lifecycle_attestation_digest",
            "lifecycle_attestation_valid_until",
            "consumer_subject_id",
            "consumer_audience",
            "consumer_contract_id",
            "consumer_contract_version",
            "purpose_id",
            "policy_id",
            "policy_version",
            "policy_digest",
            "issued_at",
            "valid_until",
            "effective_until",
            "single_use",
            "renewable",
            "transferable",
        )
        if (
            any(getattr(row, name) != getattr(lease, name) for name in scalar_fields)
            or row.organization_id != lease.scope.organization_id
            or row.environment_id != lease.scope.environment_id
            or row.site_id != lease.scope.site_id
            or row.lease_is_bearer_capability != getattr(lease, "lease_is_bearer_capability", False)
            or row.state != lease.state.value
            or any(getattr(row, name) != value for name, value in authority_columns.items())
            or row.authorization_evidence_digest != canonical_digest(evidence_payload)
            or row.authorization_audit_digest != canonical_digest(audit_payload)
            or dict(row.authorization_audit_payload) != audit_payload
            or row.canonical_digest != lease.canonical_digest
            or row.payload != lease.canonical_value()
            or row.capsule_is_bearer_capability != attestation.capsule_is_bearer_capability
            or row.lifecycle_attestation_id != attestation.attestation_id
            or row.lifecycle_attestation_digest != attestation.canonical_digest
            or row.lifecycle_attestation_valid_until != attestation.valid_until
            or row.lifecycle_attestor_id
            != cls._capsule_lifecycle_attestation_value(
                attestation, "protected_store_attestor_id", "capsule_lifecycle_attestor_id"
            )
            or row.lifecycle_attestor_version
            != cls._capsule_lifecycle_attestation_value(
                attestation,
                "protected_store_attestor_version",
                "capsule_lifecycle_attestor_version",
            )
            or row.lifecycle_signing_key_id != attestation.signing_key_id
            or row.lifecycle_signature_algorithm != attestation.signature_algorithm
            or row.lifecycle_integrity_signature != attestation.integrity_signature
        ):
            cls._target_context_capsule_handoff_contract_violation()
        return lease

    @staticmethod
    def _target_context_capsule_handoff_attestation_from_payload(
        payload: dict[str, Any],
    ) -> WorkflowProtectedTargetContextCapsuleLifecycleAttestation:
        values = dict(payload)
        values.pop("canonical_digest", None)
        values["observed_at"] = datetime.fromisoformat(str(values["observed_at"]))
        values["valid_until"] = datetime.fromisoformat(str(values["valid_until"]))
        return WorkflowProtectedTargetContextCapsuleLifecycleAttestation(
            **cast(Any, values),
            canonical_digest=str(payload["canonical_digest"]),
        )

    @classmethod
    def _target_context_capsule_handoff_claim_model(
        cls,
        request: WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseRequest,
        *,
        evidence_payload: dict[str, object],
    ) -> WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationClaimModel:
        del evidence_payload
        lease = request.candidate
        scope_id = cls._target_context_capsule_handoff_idempotency_scope(
            request.scope,
            request.consumer_subject_id,
            request.consumer_audience,
        )
        audit_payload = cls._target_context_capsule_handoff_authorization_audit_payload(lease)
        payload = cls._target_context_capsule_handoff_claim_payload(
            request=request,
            lease=lease,
            scope_id=scope_id,
            audit_payload=audit_payload,
        )
        digest = canonical_digest(payload)
        return WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationClaimModel(
            claim_id=f"workflow-tctx-capsule-handoff-claim.{digest[:48]}",
            idempotency_scope_id=scope_id,
            idempotency_key=request.idempotency_key,
            idempotency_digest=cls._target_context_capsule_handoff_idempotency_digest(request),
            request_fingerprint=request.request_fingerprint,
            result_digest=lease.canonical_digest,
            authorization_lease_id=lease.authorization_lease_id,
            consumer_binding_id=lease.consumer_binding_id,
            sealed_capsule_id=lease.sealed_capsule_id,
            consumer_subject_id=lease.consumer_subject_id,
            consumer_audience=lease.consumer_audience,
            consumer_contract_id=lease.consumer_contract_id,
            consumer_contract_version=lease.consumer_contract_version,
            purpose_id=lease.purpose_id,
            policy_id=lease.policy_id,
            policy_version=lease.policy_version,
            policy_digest=lease.policy_digest,
            organization_id=lease.scope.organization_id,
            environment_id=lease.scope.environment_id,
            site_id=lease.scope.site_id,
            created_at=lease.issued_at,
            authorization_audit_digest=canonical_digest(audit_payload),
            canonical_digest=digest,
            payload=payload,
            authorization_audit_payload=audit_payload,
        )

    @classmethod
    def _target_context_capsule_handoff_lease_from_claim(
        cls,
        claim: WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationClaimModel | None,
        lease_row: WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseModel
        | None,
    ) -> WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLease:
        if claim is None or lease_row is None:
            cls._target_context_capsule_handoff_contract_violation()
        assert claim is not None
        assert lease_row is not None
        lease = cls._target_context_capsule_handoff_lease_from_row(lease_row)
        scope_id = cls._target_context_capsule_handoff_idempotency_scope(
            lease.scope,
            lease.consumer_subject_id,
            lease.consumer_audience,
        )
        audit_payload = cls._target_context_capsule_handoff_authorization_audit_payload(lease)
        request_proxy = cast(
            Any,
            type(
                "_TargetContextCapsuleHandoffReplayRequest",
                (),
                {
                    "idempotency_key": claim.idempotency_key,
                    "request_fingerprint": claim.request_fingerprint,
                    "idempotency_digest": claim.idempotency_digest,
                },
            )(),
        )
        payload = cls._target_context_capsule_handoff_claim_payload(
            request=request_proxy,
            lease=lease,
            scope_id=scope_id,
            audit_payload=audit_payload,
        )
        if (
            claim.idempotency_scope_id != scope_id
            or claim.idempotency_digest
            != cls._target_context_capsule_handoff_idempotency_digest(request_proxy)
            or claim.result_digest != lease.canonical_digest
            or claim.authorization_lease_id != lease.authorization_lease_id
            or claim.consumer_binding_id != lease.consumer_binding_id
            or claim.sealed_capsule_id != lease.sealed_capsule_id
            or claim.consumer_subject_id != lease.consumer_subject_id
            or claim.consumer_audience != lease.consumer_audience
            or claim.consumer_contract_id != lease.consumer_contract_id
            or claim.consumer_contract_version != lease.consumer_contract_version
            or claim.purpose_id != lease.purpose_id
            or claim.policy_id != lease.policy_id
            or claim.policy_version != lease.policy_version
            or claim.policy_digest != lease.policy_digest
            or claim.organization_id != lease.scope.organization_id
            or claim.environment_id != lease.scope.environment_id
            or claim.site_id != lease.scope.site_id
            or claim.created_at != lease.issued_at
            or claim.authorization_audit_digest != canonical_digest(audit_payload)
            or dict(claim.authorization_audit_payload) != audit_payload
            or claim.payload != payload
            or claim.canonical_digest != canonical_digest(payload)
        ):
            cls._target_context_capsule_handoff_contract_violation()
        return lease

    @staticmethod
    def _target_context_capsule_handoff_claim_payload(
        *,
        request: Any,
        lease: WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLease,
        scope_id: str,
        audit_payload: dict[str, object],
    ) -> dict[str, object]:
        return {
            "authorization_audit_digest": canonical_digest(audit_payload),
            "authorization_audit_payload": audit_payload,
            "idempotency_digest": (
                PostgreSQLWorkflowPlanRepository._target_context_capsule_handoff_idempotency_digest(
                    request
                )
            ),
            "idempotency_key": request.idempotency_key,
            "idempotency_scope_id": scope_id,
            "request_fingerprint": request.request_fingerprint,
            "result_digest": lease.canonical_digest,
            "result_lease": lease.canonical_value(),
        }

    @staticmethod
    def _target_context_capsule_handoff_authorization_audit_payload(
        lease: WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLease,
    ) -> dict[str, object]:
        return {
            "authority": lease.authority.canonical_value(),
            "lifecycle_attestation_digest": lease.lifecycle_attestation_digest,
            "consumer_audience": lease.consumer_audience,
            "consumer_binding_digest": lease.consumer_binding_digest,
            "consumer_binding_id": lease.consumer_binding_id,
            "consumer_contract_id": lease.consumer_contract_id,
            "consumer_contract_version": lease.consumer_contract_version,
            "consumer_subject_id": lease.consumer_subject_id,
            "authorization_lease_id": lease.authorization_lease_id,
            "policy_digest": lease.policy_digest,
            "policy_id": lease.policy_id,
            "policy_version": lease.policy_version,
            "purpose_id": lease.purpose_id,
            "schema_id": "audit.workflow-target-context-capsule-handoff-authorization",
            "schema_version": "1.0",
            "scope": lease.scope.canonical_value(),
        }

    @staticmethod
    def _target_context_capsule_handoff_idempotency_digest(request: Any) -> str:
        value = getattr(request, "idempotency_digest", None)
        if isinstance(value, str):
            return value
        return canonical_digest(
            {
                "idempotency_key": request.idempotency_key,
                "request_fingerprint": request.request_fingerprint,
            }
        )

    @staticmethod
    def _target_context_capsule_handoff_idempotency_scope(
        scope: WorkflowScope,
        consumer_subject_id: str,
        consumer_audience: str,
    ) -> str:
        return canonical_digest(
            {
                "consumer_audience": consumer_audience,
                "consumer_subject_id": consumer_subject_id,
                "operation": "authorize-workflow-target-context-capsule-handoff",
                "scope": scope.canonical_value(),
            }
        )

    @staticmethod
    def _target_context_capsule_handoff_contract_violation() -> NoReturn:
        raise WorkflowProtectedTransportTargetContextCapsuleHandoffAuthorizationLeaseError(
            "workflow_target_context_capsule_handoff_repository_contract_violation",
            "Stored target-context capsule handoff authorization evidence is invalid.",
        )

    async def _lock_target_context_sources(
        self,
        session: AsyncSession,
        *,
        request: WorkflowEventPhysicalTransportTargetContextBindingRequest,
    ) -> _TargetContextLockedSources | None:
        endpoint_result_seed = await session.get(
            WorkflowEventPhysicalTransportEndpointMaterializationResultModel,
            request.expected_endpoint_materialization_id,
        )
        credential_result_seed = await session.get(
            WorkflowEventPhysicalTransportCredentialMaterializationResultModel,
            request.expected_credential_materialization_id,
        )
        if endpoint_result_seed is None or credential_result_seed is None:
            return None
        endpoint_attempt_seed = await session.get(
            WorkflowEventPhysicalTransportEndpointMaterializationAttemptModel,
            endpoint_result_seed.attempt_id,
        )
        credential_attempt_seed = await session.get(
            WorkflowEventPhysicalTransportCredentialMaterializationAttemptModel,
            credential_result_seed.attempt_id,
        )
        if endpoint_attempt_seed is None or credential_attempt_seed is None:
            return None
        scope_id = self._target_context_binding_idempotency_scope(
            request.scope, request.binder_subject_id
        )
        claim_seed = cast(
            WorkflowEventPhysicalTransportTargetContextBindingClaimModel | None,
            await session.scalar(
                select(WorkflowEventPhysicalTransportTargetContextBindingClaimModel).where(
                    WorkflowEventPhysicalTransportTargetContextBindingClaimModel.idempotency_scope_id
                    == scope_id,
                    WorkflowEventPhysicalTransportTargetContextBindingClaimModel.idempotency_key
                    == request.idempotency_key,
                )
            ),
        )

        route_binding = cast(
            WorkflowEventPhysicalTransportRouteBindingModel | None,
            await session.scalar(
                select(WorkflowEventPhysicalTransportRouteBindingModel)
                .where(
                    WorkflowEventPhysicalTransportRouteBindingModel.binding_id
                    == endpoint_attempt_seed.physical_transport_route_binding_id
                )
                .with_for_update()
            ),
        )
        route_snapshot = cast(
            EventPhysicalTransportRouteSnapshotModel | None,
            await session.scalar(
                select(EventPhysicalTransportRouteSnapshotModel)
                .where(
                    EventPhysicalTransportRouteSnapshotModel.snapshot_id
                    == endpoint_attempt_seed.transport_route_snapshot_id
                )
                .with_for_update()
            ),
        )
        endpoint_freshness = cast(
            WorkflowEventPhysicalTransportRouteFreshnessAdmissionModel | None,
            await session.scalar(
                select(WorkflowEventPhysicalTransportRouteFreshnessAdmissionModel)
                .where(
                    WorkflowEventPhysicalTransportRouteFreshnessAdmissionModel.freshness_admission_id
                    == endpoint_result_seed.freshness_admission_id
                )
                .with_for_update()
            ),
        )
        endpoint_lease = cast(
            WorkflowEventPhysicalTransportEndpointResolutionAuthorizationLeaseModel | None,
            await session.scalar(
                select(WorkflowEventPhysicalTransportEndpointResolutionAuthorizationLeaseModel)
                .where(
                    WorkflowEventPhysicalTransportEndpointResolutionAuthorizationLeaseModel.authorization_lease_id
                    == endpoint_result_seed.authorization_lease_id
                )
                .with_for_update()
            ),
        )
        endpoint_claim = cast(
            WorkflowEventPhysicalTransportEndpointResolutionLeaseConsumptionClaimModel | None,
            await session.scalar(
                select(WorkflowEventPhysicalTransportEndpointResolutionLeaseConsumptionClaimModel)
                .where(
                    WorkflowEventPhysicalTransportEndpointResolutionLeaseConsumptionClaimModel.claim_id
                    == endpoint_result_seed.consumption_claim_id
                )
                .with_for_update()
            ),
        )
        endpoint_attempt = cast(
            WorkflowEventPhysicalTransportEndpointMaterializationAttemptModel | None,
            await session.scalar(
                select(WorkflowEventPhysicalTransportEndpointMaterializationAttemptModel)
                .where(
                    WorkflowEventPhysicalTransportEndpointMaterializationAttemptModel.attempt_id
                    == endpoint_result_seed.attempt_id
                )
                .with_for_update()
            ),
        )
        endpoint_result = cast(
            WorkflowEventPhysicalTransportEndpointMaterializationResultModel | None,
            await session.scalar(
                select(WorkflowEventPhysicalTransportEndpointMaterializationResultModel)
                .where(
                    WorkflowEventPhysicalTransportEndpointMaterializationResultModel.materialization_id
                    == request.expected_endpoint_materialization_id
                )
                .with_for_update()
            ),
        )
        credential_binding = cast(
            WorkflowEventPhysicalTransportCredentialAssignmentBindingModel | None,
            await session.scalar(
                select(WorkflowEventPhysicalTransportCredentialAssignmentBindingModel)
                .where(
                    WorkflowEventPhysicalTransportCredentialAssignmentBindingModel.binding_id
                    == credential_attempt_seed.physical_transport_credential_assignment_binding_id
                )
                .with_for_update()
            ),
        )
        credential_snapshot = cast(
            EventPhysicalTransportCredentialAssignmentSnapshotModel | None,
            await session.scalar(
                select(EventPhysicalTransportCredentialAssignmentSnapshotModel)
                .where(
                    EventPhysicalTransportCredentialAssignmentSnapshotModel.snapshot_id
                    == credential_attempt_seed.credential_assignment_snapshot_id
                )
                .with_for_update()
            ),
        )
        credential_freshness = cast(
            WorkflowEventPhysicalTransportCredentialAssignmentFreshnessAdmissionModel | None,
            await session.scalar(
                select(WorkflowEventPhysicalTransportCredentialAssignmentFreshnessAdmissionModel)
                .where(
                    WorkflowEventPhysicalTransportCredentialAssignmentFreshnessAdmissionModel.freshness_admission_id
                    == credential_result_seed.freshness_admission_id
                )
                .with_for_update()
            ),
        )
        credential_lease = cast(
            WorkflowEventPhysicalTransportCredentialAccessAuthorizationLeaseModel | None,
            await session.scalar(
                select(WorkflowEventPhysicalTransportCredentialAccessAuthorizationLeaseModel)
                .where(
                    WorkflowEventPhysicalTransportCredentialAccessAuthorizationLeaseModel.authorization_lease_id
                    == credential_result_seed.authorization_lease_id
                )
                .with_for_update()
            ),
        )
        credential_claim = cast(
            WorkflowEventPhysicalTransportCredentialAccessLeaseConsumptionClaimModel | None,
            await session.scalar(
                select(WorkflowEventPhysicalTransportCredentialAccessLeaseConsumptionClaimModel)
                .where(
                    WorkflowEventPhysicalTransportCredentialAccessLeaseConsumptionClaimModel.claim_id
                    == credential_result_seed.consumption_claim_id
                )
                .with_for_update()
            ),
        )
        credential_attempt = cast(
            WorkflowEventPhysicalTransportCredentialMaterializationAttemptModel | None,
            await session.scalar(
                select(WorkflowEventPhysicalTransportCredentialMaterializationAttemptModel)
                .where(
                    WorkflowEventPhysicalTransportCredentialMaterializationAttemptModel.attempt_id
                    == credential_result_seed.attempt_id
                )
                .with_for_update()
            ),
        )
        credential_result = cast(
            WorkflowEventPhysicalTransportCredentialMaterializationResultModel | None,
            await session.scalar(
                select(WorkflowEventPhysicalTransportCredentialMaterializationResultModel)
                .where(
                    WorkflowEventPhysicalTransportCredentialMaterializationResultModel.materialization_id
                    == request.expected_credential_materialization_id
                )
                .with_for_update()
            ),
        )
        required = (
            route_binding,
            route_snapshot,
            endpoint_freshness,
            endpoint_lease,
            endpoint_claim,
            endpoint_attempt,
            endpoint_result,
            credential_binding,
            credential_snapshot,
            credential_freshness,
            credential_lease,
            credential_claim,
            credential_attempt,
            credential_result,
        )
        if any(row is None for row in required):
            return None

        binding_conditions = [
            WorkflowEventPhysicalTransportTargetContextBindingModel.endpoint_materialization_id
            == request.expected_endpoint_materialization_id,
            WorkflowEventPhysicalTransportTargetContextBindingModel.credential_materialization_id
            == request.expected_credential_materialization_id,
        ]
        if claim_seed is not None:
            binding_conditions.append(
                WorkflowEventPhysicalTransportTargetContextBindingModel.binding_id
                == claim_seed.binding_id
            )
        existing_bindings = tuple(
            (
                await session.scalars(
                    select(WorkflowEventPhysicalTransportTargetContextBindingModel)
                    .where(or_(*binding_conditions))
                    .order_by(WorkflowEventPhysicalTransportTargetContextBindingModel.binding_id)
                    .with_for_update()
                )
            ).all()
        )
        idempotency_claim = cast(
            WorkflowEventPhysicalTransportTargetContextBindingClaimModel | None,
            await session.scalar(
                select(WorkflowEventPhysicalTransportTargetContextBindingClaimModel)
                .where(
                    WorkflowEventPhysicalTransportTargetContextBindingClaimModel.idempotency_scope_id
                    == scope_id,
                    WorkflowEventPhysicalTransportTargetContextBindingClaimModel.idempotency_key
                    == request.idempotency_key,
                )
                .with_for_update()
            ),
        )
        return _TargetContextLockedSources(
            route_binding=cast(WorkflowEventPhysicalTransportRouteBindingModel, route_binding),
            route_snapshot=cast(EventPhysicalTransportRouteSnapshotModel, route_snapshot),
            endpoint_freshness=cast(
                WorkflowEventPhysicalTransportRouteFreshnessAdmissionModel, endpoint_freshness
            ),
            endpoint_lease=cast(
                WorkflowEventPhysicalTransportEndpointResolutionAuthorizationLeaseModel,
                endpoint_lease,
            ),
            endpoint_claim=cast(
                WorkflowEventPhysicalTransportEndpointResolutionLeaseConsumptionClaimModel,
                endpoint_claim,
            ),
            endpoint_attempt=cast(
                WorkflowEventPhysicalTransportEndpointMaterializationAttemptModel,
                endpoint_attempt,
            ),
            endpoint_result=cast(
                WorkflowEventPhysicalTransportEndpointMaterializationResultModel, endpoint_result
            ),
            credential_binding=cast(
                WorkflowEventPhysicalTransportCredentialAssignmentBindingModel,
                credential_binding,
            ),
            credential_snapshot=cast(
                EventPhysicalTransportCredentialAssignmentSnapshotModel, credential_snapshot
            ),
            credential_freshness=cast(
                WorkflowEventPhysicalTransportCredentialAssignmentFreshnessAdmissionModel,
                credential_freshness,
            ),
            credential_lease=cast(
                WorkflowEventPhysicalTransportCredentialAccessAuthorizationLeaseModel,
                credential_lease,
            ),
            credential_claim=cast(
                WorkflowEventPhysicalTransportCredentialAccessLeaseConsumptionClaimModel,
                credential_claim,
            ),
            credential_attempt=cast(
                WorkflowEventPhysicalTransportCredentialMaterializationAttemptModel,
                credential_attempt,
            ),
            credential_result=cast(
                WorkflowEventPhysicalTransportCredentialMaterializationResultModel,
                credential_result,
            ),
            existing_bindings=existing_bindings,
            idempotency_claim=idempotency_claim,
        )

    def _target_context_binding_replay(
        self,
        locked: _TargetContextLockedSources,
        *,
        request: WorkflowEventPhysicalTransportTargetContextBindingRequest,
        observed_at: datetime,
    ) -> WorkflowEventPhysicalTransportTargetContextBindingResult | None:
        claim = locked.idempotency_claim
        if claim is None:
            return None
        binding_row = next(
            (row for row in locked.existing_bindings if row.binding_id == claim.binding_id),
            None,
        )
        if binding_row is None:
            self._target_context_binding_contract_violation()
        binding = self._target_context_binding_from_claim(claim, binding_row=binding_row)
        exact = (
            claim.request_fingerprint == request.request_fingerprint
            and binding.endpoint_materialization_id == request.expected_endpoint_materialization_id
            and binding.endpoint_materialization_digest
            == request.expected_endpoint_materialization_digest
            and binding.credential_materialization_id
            == request.expected_credential_materialization_id
            and binding.credential_materialization_digest
            == request.expected_credential_materialization_digest
            and binding.policy_id == request.expected_policy_id
            and binding.policy_version == request.expected_policy_version
            and binding.policy_digest == request.expected_policy_digest
            and binding.scope == request.scope
            and binding.binder_subject_id == request.binder_subject_id
        )
        if exact:
            evidence = self._target_context_binding_evidence(
                locked,
                request=request,
                observed_at=observed_at,
                require_live_overlap=False,
            )
            if evidence is None:
                self._target_context_binding_contract_violation()
        status = (
            WorkflowEventPhysicalTransportTargetContextBindingStatus.REPLAY
            if exact
            else WorkflowEventPhysicalTransportTargetContextBindingStatus.IDEMPOTENCY_CONFLICT
        )
        return WorkflowEventPhysicalTransportTargetContextBindingResult(
            status, binding if exact else None
        )

    @classmethod
    def _target_context_binding_evidence(
        cls,
        locked: _TargetContextLockedSources,
        *,
        request: WorkflowEventPhysicalTransportTargetContextBindingRequest,
        observed_at: datetime,
        require_live_overlap: bool,
    ) -> dict[str, Any] | None:
        try:
            route_binding = cls._physical_transport_route_binding_from_row(locked.route_binding)
            route_snapshot = cls._transport_route_snapshot_from_row(locked.route_snapshot)
            endpoint_freshness = cls._route_freshness_admission_from_row(locked.endpoint_freshness)
            endpoint_lease = cls._endpoint_resolution_authorization_lease_from_row(
                locked.endpoint_lease
            )
            endpoint_claim = cls._endpoint_materialization_claim_from_row(locked.endpoint_claim)
            endpoint_attempt = cls._endpoint_materialization_attempt_from_row(
                locked.endpoint_attempt
            )
            endpoint_result = cls._endpoint_materialization_result_from_row(locked.endpoint_result)
            credential_binding = cls._credential_assignment_binding_from_row(
                locked.credential_binding
            )
            credential_snapshot = cls._credential_assignment_snapshot_from_row(
                locked.credential_snapshot
            )
            credential_freshness = cls._credential_assignment_freshness_admission_from_row(
                locked.credential_freshness
            )
            credential_lease = cls._credential_access_lease_from_row(locked.credential_lease)
            credential_claim = cls._credential_materialization_claim_from_row(
                locked.credential_claim
            )
            credential_attempt = cls._credential_materialization_attempt_from_row(
                locked.credential_attempt
            )
            credential_result = cls._credential_materialization_result_from_row(
                locked.credential_result
            )
        except Exception as exc:
            raise WorkflowEventPhysicalTransportTargetContextBindingError(
                "workflow_target_context_binding_repository_contract_violation",
                "Target-context source evidence is invalid.",
            ) from exc

        scope = request.scope
        objects = (
            route_binding,
            route_snapshot,
            endpoint_freshness,
            endpoint_lease,
            endpoint_claim,
            endpoint_attempt,
            endpoint_result,
            credential_binding,
            credential_snapshot,
            credential_freshness,
            credential_lease,
            credential_claim,
            credential_attempt,
            credential_result,
        )
        if any(item.scope != scope for item in objects):
            return None
        zero_authority_objects = (
            route_binding,
            route_snapshot,
            endpoint_freshness,
            endpoint_claim,
            endpoint_attempt,
            endpoint_result,
            credential_binding,
            credential_snapshot,
            credential_freshness,
            credential_claim,
            credential_attempt,
            credential_result,
        )
        if any(any(item.authority.canonical_value().values()) for item in zero_authority_objects):
            return None

        if (
            endpoint_result.materialization_id != request.expected_endpoint_materialization_id
            or endpoint_result.canonical_digest != request.expected_endpoint_materialization_digest
            or endpoint_result.state.value != "materialized_protected"
            or endpoint_result.failure_class is not None
            or endpoint_result.protected_artifact_id is None
            or endpoint_result.protected_artifact_digest is None
            or endpoint_result.usable_until is None
            or endpoint_result.protected_artifact_revoked is not False
            or endpoint_result.cleanup_confirmed is not True
            or credential_result.materialization_id
            != request.expected_credential_materialization_id
            or credential_result.canonical_digest
            != request.expected_credential_materialization_digest
            or credential_result.state.value != "materialized_protected"
            or credential_result.failure_class is not None
            or credential_result.protected_artifact_id is None
            or credential_result.protected_artifact_digest is None
            or credential_result.usable_until is None
            or credential_result.protected_artifact_revoked is not False
            or credential_result.cleanup_confirmed is not True
        ):
            return None
        if require_live_overlap and not (
            observed_at < endpoint_result.usable_until
            and observed_at < credential_result.usable_until
        ):
            return None

        endpoint_chain_matches = (
            route_binding.transport_route_snapshot_id == route_snapshot.snapshot_id
            and route_binding.transport_route_snapshot_digest == route_snapshot.canonical_digest
            and endpoint_freshness.physical_transport_route_binding_id == route_binding.binding_id
            and endpoint_freshness.physical_transport_route_binding_digest
            == route_binding.canonical_digest
            and endpoint_freshness.transport_route_snapshot_id == route_snapshot.snapshot_id
            and endpoint_freshness.transport_route_snapshot_digest
            == route_snapshot.canonical_digest
            and endpoint_lease.freshness_admission_id == endpoint_freshness.freshness_admission_id
            and endpoint_lease.freshness_admission_digest == endpoint_freshness.canonical_digest
            and endpoint_lease.physical_transport_route_binding_id == route_binding.binding_id
            and endpoint_lease.physical_transport_route_binding_digest
            == route_binding.canonical_digest
            and endpoint_lease.transport_route_snapshot_id == route_snapshot.snapshot_id
            and endpoint_lease.transport_route_snapshot_digest == route_snapshot.canonical_digest
            and endpoint_claim.authorization_lease_id == endpoint_lease.authorization_lease_id
            and endpoint_claim.authorization_lease_digest == endpoint_lease.canonical_digest
            and endpoint_claim.freshness_admission_id == endpoint_freshness.freshness_admission_id
            and endpoint_claim.freshness_admission_digest == endpoint_freshness.canonical_digest
            and endpoint_attempt.consumption_claim_id == endpoint_claim.claim_id
            and endpoint_attempt.authorization_lease_id == endpoint_lease.authorization_lease_id
            and endpoint_attempt.authorization_lease_digest == endpoint_lease.canonical_digest
            and endpoint_attempt.freshness_admission_id == endpoint_freshness.freshness_admission_id
            and endpoint_attempt.freshness_admission_digest == endpoint_freshness.canonical_digest
            and endpoint_attempt.physical_transport_route_binding_id == route_binding.binding_id
            and endpoint_attempt.physical_transport_route_binding_digest
            == route_binding.canonical_digest
            and endpoint_attempt.transport_route_snapshot_id == route_snapshot.snapshot_id
            and endpoint_attempt.transport_route_snapshot_digest == route_snapshot.canonical_digest
            and endpoint_attempt.attempt_id == endpoint_claim.attempt_id
            and endpoint_attempt.materialization_id == endpoint_claim.materialization_id
            and endpoint_result.attempt_id == endpoint_attempt.attempt_id
            and endpoint_result.attempt_digest == endpoint_attempt.canonical_digest
            and endpoint_result.consumption_claim_id == endpoint_claim.claim_id
            and endpoint_result.consumption_claim_digest == endpoint_claim.canonical_digest
            and endpoint_result.authorization_lease_id == endpoint_lease.authorization_lease_id
            and endpoint_result.authorization_lease_digest == endpoint_lease.canonical_digest
            and endpoint_result.freshness_admission_id == endpoint_freshness.freshness_admission_id
            and endpoint_result.freshness_admission_digest == endpoint_freshness.canonical_digest
            and endpoint_result.transport_route_snapshot_id == route_snapshot.snapshot_id
            and endpoint_result.transport_route_snapshot_digest == route_snapshot.canonical_digest
            and endpoint_result.resolver_subject_id == endpoint_lease.resolver_subject_id
        )
        credential_chain_matches = (
            credential_binding.physical_transport_route_binding_id == route_binding.binding_id
            and credential_binding.physical_transport_route_binding_digest
            == route_binding.canonical_digest
            and credential_binding.transport_route_snapshot_id == route_snapshot.snapshot_id
            and credential_binding.transport_route_snapshot_digest
            == route_snapshot.canonical_digest
            and credential_binding.credential_assignment_snapshot_id
            == credential_snapshot.snapshot_id
            and credential_binding.credential_assignment_snapshot_digest
            == credential_snapshot.canonical_digest
            and credential_snapshot.route_snapshot_id == route_snapshot.snapshot_id
            and credential_snapshot.route_id == route_snapshot.route_id
            and credential_snapshot.route_revision == route_snapshot.route_revision
            and credential_snapshot.source_route_digest == route_snapshot.source_route_digest
            and credential_snapshot.credential_requirement_profile_id
            == route_snapshot.credential_requirement_profile_id
            and credential_snapshot.credential_requirement_profile_version
            == route_snapshot.credential_requirement_profile_version
            and credential_snapshot.credential_requirement_profile_digest
            == route_snapshot.credential_requirement_profile_digest
            and credential_snapshot.authentication_mechanism_class
            == route_snapshot.authentication_mechanism_class
            and credential_snapshot.principal_class == route_snapshot.principal_class
            and credential_freshness.physical_transport_credential_assignment_binding_id
            == credential_binding.binding_id
            and credential_freshness.physical_transport_credential_assignment_binding_digest
            == credential_binding.canonical_digest
            and credential_freshness.credential_assignment_snapshot_id
            == credential_snapshot.snapshot_id
            and credential_freshness.credential_assignment_snapshot_digest
            == credential_snapshot.canonical_digest
            and credential_lease.freshness_admission_id
            == credential_freshness.freshness_admission_id
            and credential_lease.freshness_admission_digest == credential_freshness.canonical_digest
            and credential_lease.physical_transport_credential_assignment_binding_id
            == credential_binding.binding_id
            and credential_lease.physical_transport_credential_assignment_binding_digest
            == credential_binding.canonical_digest
            and credential_lease.credential_assignment_snapshot_id
            == credential_snapshot.snapshot_id
            and credential_lease.credential_assignment_snapshot_digest
            == credential_snapshot.canonical_digest
            and credential_claim.authorization_lease_id == credential_lease.authorization_lease_id
            and credential_claim.authorization_lease_digest == credential_lease.canonical_digest
            and credential_claim.freshness_admission_id
            == credential_freshness.freshness_admission_id
            and credential_claim.freshness_admission_digest == credential_freshness.canonical_digest
            and credential_attempt.consumption_claim_id == credential_claim.claim_id
            and credential_attempt.authorization_lease_id == credential_lease.authorization_lease_id
            and credential_attempt.authorization_lease_digest == credential_lease.canonical_digest
            and credential_attempt.freshness_admission_id
            == credential_freshness.freshness_admission_id
            and credential_attempt.freshness_admission_digest
            == credential_freshness.canonical_digest
            and credential_attempt.physical_transport_credential_assignment_binding_id
            == credential_binding.binding_id
            and credential_attempt.physical_transport_credential_assignment_binding_digest
            == credential_binding.canonical_digest
            and credential_attempt.credential_assignment_snapshot_id
            == credential_snapshot.snapshot_id
            and credential_attempt.credential_assignment_snapshot_digest
            == credential_snapshot.canonical_digest
            and credential_attempt.attempt_id == credential_claim.attempt_id
            and credential_attempt.materialization_id == credential_claim.materialization_id
            and credential_result.attempt_id == credential_attempt.attempt_id
            and credential_result.attempt_digest == credential_attempt.canonical_digest
            and credential_result.consumption_claim_id == credential_claim.claim_id
            and credential_result.consumption_claim_digest == credential_claim.canonical_digest
            and credential_result.authorization_lease_id == credential_lease.authorization_lease_id
            and credential_result.authorization_lease_digest == credential_lease.canonical_digest
            and credential_result.freshness_admission_id
            == credential_freshness.freshness_admission_id
            and credential_result.freshness_admission_digest
            == credential_freshness.canonical_digest
            and credential_result.credential_assignment_snapshot_id
            == credential_snapshot.snapshot_id
            and credential_result.credential_assignment_snapshot_digest
            == credential_snapshot.canonical_digest
            and credential_result.assignment_id == credential_snapshot.assignment_id
            and credential_result.assignment_revision == credential_snapshot.assignment_revision
            and credential_result.credential_generation == credential_snapshot.credential_generation
            and credential_result.rotation_epoch == credential_snapshot.rotation_epoch
            and credential_result.accessor_subject_id == credential_lease.accessor_subject_id
        )
        if not endpoint_chain_matches or not credential_chain_matches:
            return None
        return {
            "route_binding": route_binding,
            "route_snapshot": route_snapshot,
            "endpoint_result": endpoint_result,
            "credential_binding": credential_binding,
            "credential_snapshot": credential_snapshot,
            "credential_result": credential_result,
        }

    @classmethod
    def _target_context_binding(
        cls,
        *,
        request: WorkflowEventPhysicalTransportTargetContextBindingRequest,
        evidence: dict[str, Any],
        bound_at: datetime,
    ) -> WorkflowEventPhysicalTransportTargetContextBinding:
        policy = code_owned_workflow_event_physical_transport_target_context_binding_policy()
        route_binding = evidence["route_binding"]
        route_snapshot = evidence["route_snapshot"]
        endpoint_result = evidence["endpoint_result"]
        credential_binding = evidence["credential_binding"]
        credential_snapshot = evidence["credential_snapshot"]
        credential_result = evidence["credential_result"]
        commitment = cls._target_context_commitment(evidence=evidence, policy=policy)
        identity_digest = canonical_digest(
            {
                "binder_subject_id": request.binder_subject_id,
                "request_fingerprint": request.request_fingerprint,
                "target_context_commitment": commitment,
            }
        )
        values: dict[str, object] = {
            "binding_id": f"workflow-target-context-binding.{identity_digest[:48]}",
            "physical_transport_route_binding_id": route_binding.binding_id,
            "physical_transport_route_binding_digest": route_binding.canonical_digest,
            "transport_route_snapshot_id": route_snapshot.snapshot_id,
            "transport_route_snapshot_digest": route_snapshot.canonical_digest,
            "endpoint_materialization_id": endpoint_result.materialization_id,
            "endpoint_materialization_digest": endpoint_result.canonical_digest,
            "physical_transport_credential_assignment_binding_id": credential_binding.binding_id,
            "physical_transport_credential_assignment_binding_digest": (
                credential_binding.canonical_digest
            ),
            "credential_assignment_snapshot_id": credential_snapshot.snapshot_id,
            "credential_assignment_snapshot_digest": credential_snapshot.canonical_digest,
            "credential_materialization_id": credential_result.materialization_id,
            "credential_materialization_digest": credential_result.canonical_digest,
            "resolver_subject_id": endpoint_result.resolver_subject_id,
            "accessor_subject_id": credential_result.accessor_subject_id,
            "target_context_schema_id": policy.target_context_schema_id,
            "target_context_schema_version": policy.target_context_schema_version,
            "target_context_commitment": commitment,
            "scope": request.scope,
            "binder_subject_id": request.binder_subject_id,
            "bound_at": bound_at,
            "joint_usable_until": min(endpoint_result.usable_until, credential_result.usable_until),
            "policy_id": policy.policy_id,
            "policy_version": policy.policy_version,
            "policy_digest": policy.canonical_digest,
            "state": WorkflowEventPhysicalTransportTargetContextBindingState.BOUND,
            "authority": WorkflowEventPhysicalTransportTargetContextBindingAuthority(),
        }
        payload = cls._target_context_binding_payload_values(values)
        return WorkflowEventPhysicalTransportTargetContextBinding(
            **cast(Any, values), canonical_digest=canonical_digest(payload)
        )

    @staticmethod
    def _target_context_commitment(*, evidence: dict[str, Any], policy: Any) -> str:
        route_binding = evidence["route_binding"]
        route_snapshot = evidence["route_snapshot"]
        endpoint_result = evidence["endpoint_result"]
        credential_binding = evidence["credential_binding"]
        credential_snapshot = evidence["credential_snapshot"]
        credential_result = evidence["credential_result"]
        return canonical_digest(
            {
                "credential_assignment_binding": {
                    "digest": credential_binding.canonical_digest,
                    "id": credential_binding.binding_id,
                },
                "credential_assignment_snapshot": {
                    "digest": credential_snapshot.canonical_digest,
                    "id": credential_snapshot.snapshot_id,
                    "target_scope_commitment": credential_snapshot.target_scope_commitment,
                },
                "credential_materialization": {
                    "digest": credential_result.canonical_digest,
                    "id": credential_result.materialization_id,
                },
                "destination": {
                    "id": route_snapshot.destination_id,
                    "revision": route_snapshot.destination_revision,
                },
                "endpoint_materialization": {
                    "digest": endpoint_result.canonical_digest,
                    "id": endpoint_result.materialization_id,
                },
                "endpoint_set": {
                    "id": route_snapshot.endpoint_set_id,
                    "revision": route_snapshot.endpoint_set_revision,
                },
                "physical_transport_route_binding": {
                    "digest": route_binding.canonical_digest,
                    "id": route_binding.binding_id,
                },
                "routing_contract": {
                    "id": route_snapshot.routing_contract_id,
                    "revision": route_snapshot.routing_contract_revision,
                },
                "schema_id": policy.target_context_schema_id,
                "schema_version": policy.target_context_schema_version,
                "scope": route_binding.scope.canonical_value(),
                "transport_route_snapshot": {
                    "digest": route_snapshot.canonical_digest,
                    "id": route_snapshot.snapshot_id,
                    "route_id": route_snapshot.route_id,
                    "route_revision": route_snapshot.route_revision,
                    "source_route_digest": route_snapshot.source_route_digest,
                },
            }
        )

    @staticmethod
    def _target_context_binding_payload_values(values: dict[str, object]) -> dict[str, object]:
        return {
            key: (
                value.canonical_value()
                if isinstance(
                    value,
                    (
                        WorkflowScope,
                        WorkflowEventPhysicalTransportTargetContextBindingAuthority,
                    ),
                )
                else value.isoformat()
                if isinstance(value, datetime)
                else value.value
                if isinstance(value, Enum)
                else value
            )
            for key, value in values.items()
        }

    @staticmethod
    def _target_context_binding_payload(
        binding: WorkflowEventPhysicalTransportTargetContextBinding,
    ) -> dict[str, object]:
        return binding.canonical_value()

